Object.assign(window.IND_FEED_BODY, {"gv-6-9":{"route":"#/gitav/6.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:9:en","title":"Bhagavad Gita 6.9","text":"सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु ।\nसाधुष्वपि च पापेषु समबुद्धिर्विशिष्यते ॥","lang":"sa","roman":"suhṛnmitrāryudāsīnamadhyasthadveṣyabandhuṣu |\nsādhuṣvapi ca pāpeṣu samabuddhirviśiṣyate ||","body":"He who regards impartially lovers, friends, and foes, strangers, neutrals, foreigners and relatives, also the righteous and unrighteous, he excelleth.","facts":[["Chapter","The Way of Meditation"],["Verse","9 of 47"]]},"g2-6-9":{"route":"#/gitav/6.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:9:en2","title":"Gita 6.9, in another translation","body":"He attains excellence who looks with equal regard upon well-wishers, friends, foes, neutrals, arbiters, the hateful, the relatives, and upon the righteous and the unrighteous alike.","facts":[["Chapter","The Way of Meditation"],["Verse","9 of 47"]]},"gv-6-10":{"route":"#/gitav/6.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:10:en","title":"Bhagavad Gita 6.10","text":"योगी युञ्जीत सततमात्मानं रहसि स्थितः ।\nएकाकी यतचित्तात्मा निराशीरपरिग्रहः ॥","lang":"sa","roman":"yogī yuñjīta satatamātmānaṃ rahasi sthitaḥ |\nekākī yatacittātmā nirāśīraparigrahaḥ ||","body":"Let the Yogî constantly engage himself in yoga, remaining in a secret place by himself, with thought and self subdued, free from hope and greed.","facts":[["Chapter","The Way of Meditation"],["Verse","10 of 47"]]},"g2-6-10":{"route":"#/gitav/6.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:10:en2","title":"Gita 6.10, in another translation","body":"The Yogi should constantly practise concentration of the heart, retiring into solitude, alone, with the mind and body subdued, and free from hope and possession.","facts":[["Chapter","The Way of Meditation"],["Verse","10 of 47"]]},"gv-6-11":{"route":"#/gitav/6.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:11:en","title":"Bhagavad Gita 6.11","text":"शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः ।\nनात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम् ॥","lang":"sa","roman":"śucau deśe pratiṣṭhāpya sthiramāsanamātmanaḥ |\nnātyucchritaṃ nātinīcaṃ cailājinakuśottaram ||","body":"In a pure place, established on a fixed seat of his own, neither very much raised nor very low, made of a cloth, a black antelope skin, and kusha grass, one over the other;","facts":[["Chapter","The Way of Meditation"],["Verse","11 of 47"]]},"g2-6-11":{"route":"#/gitav/6.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:11:en2","title":"Gita 6.11, in another translation","body":"Having in a cleanly spot established his seat, firm, neither too high nor too low, made of a cloth, a skin, and Kusha-grass, arranged in consecution:","facts":[["Chapter","The Way of Meditation"],["Verse","11 of 47"]]},"gv-6-12":{"route":"#/gitav/6.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:12:en","title":"Bhagavad Gita 6.12","text":"तत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः ।\nउपविश्यासने युञ्ज्याद्योगमात्मविशुद्धये ॥","lang":"sa","roman":"tatraikāgraṃ manaḥ kṛtvā yatacittendriyakriyaḥ |\nupaviśyāsane yuñjyādyogamātmaviśuddhaye ||","body":"There, having made the mind one-pointed, with thought and the functions of the senses subdued, steady on his seat, he should practise yoga for the purification of the self.","facts":[["Chapter","The Way of Meditation"],["Verse","12 of 47"]]},"g2-6-12":{"route":"#/gitav/6.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:12:en2","title":"Gita 6.12, in another translation","body":"There, seated on that seat, making the mind one-pointed and subduing the action of the imaging faculty and the senses, let him practise Yoga for the purification of the heart.","facts":[["Chapter","The Way of Meditation"],["Verse","12 of 47"]]},"gv-6-13":{"route":"#/gitav/6.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:13:en","title":"Bhagavad Gita 6.13","text":"समं कायशिरोग्रीवं धारयन्नचलं स्थिरः ।\nसंप्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन् ॥","lang":"sa","roman":"samaṃ kāyaśirogrīvaṃ dhārayannacalaṃ sthiraḥ |\nsaṃprekṣya nāsikāgraṃ svaṃ diśaścānavalokayan ||","body":"Holding the body, head and neck erect, immovably steady, looking fixedly at the point of the nose, with unseeing gaze,","facts":[["Chapter","The Way of Meditation"],["Verse","13 of 47"]]},"g2-6-13":{"route":"#/gitav/6.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:13:en2","title":"Gita 6.13, in another translation","body":"Let him firmly hold his body, head and neck erect and still, (with the eye-balls fixed, as if) gazing at the tip of his nose, and not looking around.","facts":[["Chapter","The Way of Meditation"],["Verse","13 of 47"]]},"gv-6-14":{"route":"#/gitav/6.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:14:en","title":"Bhagavad Gita 6.14","text":"प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः ।\nमनः संयम्य मच्चित्तो युक्त आसीत मत्परः ॥","lang":"sa","roman":"praśāntātmā vigatabhīrbrahmacārivrate sthitaḥ |\nmanaḥ saṃyamya maccitto yukta āsīta matparaḥ ||","body":"The self serene, fearless, firm in the vow of the Brahmachâri, the mind controlled, thinking on Me, harmonised, let him sit aspiring after Me.","facts":[["Chapter","The Way of Meditation"],["Verse","14 of 47"]]},"g2-6-14":{"route":"#/gitav/6.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:14:en2","title":"Gita 6.14, in another translation","body":"With the heart serene and fearless, firm in the vow of a Brahmachâri, with the mind controlled, and ever thinking of Me, let him sit (in Yoga) having Me as his supreme goal.","facts":[["Chapter","The Way of Meditation"],["Verse","14 of 47"]]},"gv-6-15":{"route":"#/gitav/6.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:15:en","title":"Bhagavad Gita 6.15","text":"युञ्जन्नेवं सदाऽऽत्मानं योगी नियतमानसः ।\nशान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति ॥","lang":"sa","roman":"yuñjannevaṃ sadā’’tmānaṃ yogī niyatamānasaḥ |\nśāntiṃ nirvāṇaparamāṃ matsaṃsthāmadhigacchati ||","body":"The Yogî ever united thus with the Self, with the mind controlled, goeth to Peace, to the supreme Bliss that abideth in Me.","facts":[["Chapter","The Way of Meditation"],["Verse","15 of 47"]]},"g2-6-15":{"route":"#/gitav/6.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:15:en2","title":"Gita 6.15, in another translation","body":"Thus always keeping the mind steadfast, the Yogi of subdued mind attains the peace residing in Me,—the peace which culminates in Nirvâna (Moksha).","facts":[["Chapter","The Way of Meditation"],["Verse","15 of 47"]]},"gv-6-16":{"route":"#/gitav/6.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:16:en","title":"Bhagavad Gita 6.16","text":"नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः ।\nन चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन ॥","lang":"sa","roman":"nātyaśnatastu yogo’sti na caikāntamanaśnataḥ |\nna cātisvapnaśīlasya jāgrato naiva cārjuna ||","body":"Verily yoga is not for him who eateth too much, nor who abstaineth to excess, nor who is too much addicted to sleep, nor even to wakefulness, O Arjuna.","facts":[["Chapter","The Way of Meditation"],["Verse","16 of 47"]]},"g2-6-16":{"route":"#/gitav/6.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:16:en2","title":"Gita 6.16, in another translation","body":"(Success in) Yoga is not for him who eats too much or too little—nor, O Arjuna, for him who sleeps too much or too little.","facts":[["Chapter","The Way of Meditation"],["Verse","16 of 47"]]},"gv-6-17":{"route":"#/gitav/6.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:17:en","title":"Bhagavad Gita 6.17","text":"युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु ।\nयुक्तस्वप्नावबोधस्य योगो भवति दुःखहा ॥","lang":"sa","roman":"yuktāhāravihārasya yuktaceṣṭasya karmasu |\nyuktasvapnāvabodhasya yogo bhavati duḥkhahā ||","body":"Yoga killeth out all pain for him who is regulated in eating and amusement, regulated in performing actions, regulated in sleeping and waking.","facts":[["Chapter","The Way of Meditation"],["Verse","17 of 47"]]},"g2-6-17":{"route":"#/gitav/6.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:17:en2","title":"Gita 6.17, in another translation","body":"To him who is temperate in eating and recreation, in his effort for work, and in sleep and wakefulness, Yoga becomes the destroyer of misery.","facts":[["Chapter","The Way of Meditation"],["Verse","17 of 47"]]},"gv-6-18":{"route":"#/gitav/6.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:18:en","title":"Bhagavad Gita 6.18","text":"यदा विनियतं चित्तमात्मन्येवावतिष्ठते ।\nनिःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा ॥","lang":"sa","roman":"yadā viniyataṃ cittamātmanyevāvatiṣṭhate |\nniḥspṛhaḥ sarvakāmebhyo yukta ityucyate tadā ||","body":"When his subdued thought is fixed on the Self, free from longing after all desirable things, then it is said, \"he is harmonised.\"","facts":[["Chapter","The Way of Meditation"],["Verse","18 of 47"]]},"g2-6-18":{"route":"#/gitav/6.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:18:en2","title":"Gita 6.18, in another translation","body":"When the completely controlled mind rests serenely in the Self alone, free from longing after all desires, then is one called steadfast, (in the Self).","facts":[["Chapter","The Way of Meditation"],["Verse","18 of 47"]]},"gv-6-19":{"route":"#/gitav/6.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:19:en","title":"Bhagavad Gita 6.19","text":"यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता ।\nयोगिनो यतचित्तस्य युञ्जतो योगमात्मनः ॥","lang":"sa","roman":"yathā dīpo nivātastho neṅgate sopamā smṛtā |\nyogino yatacittasya yuñjato yogamātmanaḥ ||","body":"As a lamp in a windless place flickereth not, to such is likened the Yogî of subdued thought, absorbed in the yoga of the Self.","facts":[["Chapter","The Way of Meditation"],["Verse","19 of 47"]]},"g2-6-19":{"route":"#/gitav/6.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:19:en2","title":"Gita 6.19, in another translation","body":"\"As a lamp in a spot sheltered from the wind does not flicker,\"—even such has been the simile used for a Yogi of subdued mind, practising concentration in the Self.","facts":[["Chapter","The Way of Meditation"],["Verse","19 of 47"]]},"gv-6-20":{"route":"#/gitav/6.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:20:en","title":"Bhagavad Gita 6.20","text":"यत्रोपरमते चित्तं निरुद्धं योगसेवया ।\nयत्र चैवात्मनाऽऽत्मानं पश्यन्नात्मनि तुष्यति ॥","lang":"sa","roman":"yatroparamate cittaṃ niruddhaṃ yogasevayā |\nyatra caivātmanā’’tmānaṃ paśyannātmani tuṣyati ||","body":"That in which the mind finds rest, quieted by the practice of yoga: that in which he, seeing the Self by the Self, in the Self is satisfied;","facts":[["Chapter","The Way of Meditation"],["Verse","20 of 47"]]},"g2-6-20":{"route":"#/gitav/6.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:20:en2","title":"Gita 6.20, in another translation","body":"When the mind, absolutely restrained by the practice of concentration, attains quietude, and when seeing the Self by the self, one is satisfied in his own Self; when he feels that infinite bliss—which is perceived by the (purified) intellect and which transcends the senses, and established wherein he never departs from his real state; and having obtained which, regards no other acquisition superior to that, and where established, he is not moved even by heavy sorrow;—let that be known as the state, called by the name of Yoga,—a state of severance from the contact of pain.","facts":[["Chapter","The Way of Meditation"],["Verse","20 of 47"]]},"gv-6-21":{"route":"#/gitav/6.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:21:en","title":"Bhagavad Gita 6.21","text":"सुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम् ।\nवेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः ॥","lang":"sa","roman":"sukhamātyantikaṃ yattadbuddhigrāhyamatīndriyam |\nvetti yatra na caivāyaṃ sthitaścalati tattvataḥ ||","body":"That in which he findeth the supreme delight which the Reason can grasp beyond the senses, wherein established he moveth not from the Reality;","facts":[["Chapter","The Way of Meditation"],["Verse","21 of 47"]]},"gv-6-22":{"route":"#/gitav/6.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:22:en","title":"Bhagavad Gita 6.22","text":"यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः ।\nयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते ॥","lang":"sa","roman":"yaṃ labdhvā cāparaṃ lābhaṃ manyate nādhikaṃ tataḥ |\nyasminsthito na duḥkhena guruṇāpi vicālyate ||","body":"Which, having obtained, he thinketh there is no greater gain beyond it; wherein, established, he is not shaken even by heavy sorrow;","facts":[["Chapter","The Way of Meditation"],["Verse","22 of 47"]]},"gv-6-23":{"route":"#/gitav/6.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:23:en","title":"Bhagavad Gita 6.23","text":"तं विद्याद् दुःखसंयोगवियोगं योगसंज्ञितम् ।\nस निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा ॥","lang":"sa","roman":"taṃ vidyād duḥkhasaṃyogaviyogaṃ yogasaṃjñitam |\nsa niścayena yoktavyo yogo’nirviṇṇacetasā ||","body":"That should be known by the name of yoga, this disconnection from the union with pain. This yoga must be clung to with a firm conviction and with undesponding mind.","facts":[["Chapter","The Way of Meditation"],["Verse","23 of 47"]]},"gv-6-24":{"route":"#/gitav/6.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:24:en","title":"Bhagavad Gita 6.24","text":"सङ्कल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः ।\nमनसैवेन्द्रियग्रामं विनियम्य समन्ततः ॥","lang":"sa","roman":"saṅkalpaprabhavānkāmāṃstyaktvā sarvānaśeṣataḥ |\nmanasaivendriyagrāmaṃ viniyamya samantataḥ ||","body":"Abandoning without reserve all desires born of the imagination, by the mind curbing in the aggregate of the senses on every side,","facts":[["Chapter","The Way of Meditation"],["Verse","24 of 47"]]},"g2-6-24":{"route":"#/gitav/6.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:24:en2","title":"Gita 6.24, in another translation","body":"Abandoning without reserve all desires born of Sankalpa, and completely restraining, by the mind alone, the whole group of senses from their objects in all directions;","facts":[["Chapter","The Way of Meditation"],["Verse","24 of 47"]]},"gv-6-25":{"route":"#/gitav/6.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:25:en","title":"Bhagavad Gita 6.25","text":"शनैः शनैरुपरमेद् बुद्ध्या धृतिगृहीतया ।\nआत्मसंस्थं मनः कृत्वा न किञ्चिदपि चिन्तयेत् ॥","lang":"sa","roman":"śanaiḥ śanairuparamed buddhyā dhṛtigṛhītayā |\nātmasaṃsthaṃ manaḥ kṛtvā na kiñcidapi cintayet ||","body":"Little by little let him gain tranquillity, by means of Reason controlled by steadiness; having made the mind abide in the Self, let him not think of anything.","facts":[["Chapter","The Way of Meditation"],["Verse","25 of 47"]]},"g2-6-25":{"route":"#/gitav/6.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:25:en2","title":"Gita 6.25, in another translation","body":"With the intellect set in patience, with the mind fastened on the Self, let him attain quietude by degrees: let him not think of anything.","facts":[["Chapter","The Way of Meditation"],["Verse","25 of 47"]]},"gv-6-26":{"route":"#/gitav/6.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:26:en","title":"Bhagavad Gita 6.26","text":"यतो यतो निश्चरति मनश्चञ्चलमस्थिरम् ।\nततस्ततो नियम्यैतदात्मन्येव वशं नयेत् ॥","lang":"sa","roman":"yato yato niścarati manaścañcalamasthiram |\ntatastato niyamyaitadātmanyeva vaśaṃ nayet ||","body":"As often as the wavering and unsteady mind goeth forth, so often reining it in, let him bring it under the control of the Self.","facts":[["Chapter","The Way of Meditation"],["Verse","26 of 47"]]},"g2-6-26":{"route":"#/gitav/6.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:26:en2","title":"Gita 6.26, in another translation","body":"Through whatever reason the restless, unsteady mind wanders away, let him curbing it from that, bring it under the subjugation of the Self alone.","facts":[["Chapter","The Way of Meditation"],["Verse","26 of 47"]]},"gv-6-27":{"route":"#/gitav/6.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:27:en","title":"Bhagavad Gita 6.27","text":"प्रशान्तमनसं ह्येनं योगिनं सुखमुत्तमम् ।\nउपैति शान्तरजसं ब्रह्मभूतमकल्मषम् ॥","lang":"sa","roman":"praśāntamanasaṃ hyenaṃ yoginaṃ sukhamuttamam |\nupaiti śāntarajasaṃ brahmabhūtamakalmaṣam ||","body":"Supreme joy is for this Yogi whose mind is peaceful, whose passion-nature is calmed, who is sinless and of the nature of the Eternal.","facts":[["Chapter","The Way of Meditation"],["Verse","27 of 47"]]},"g2-6-27":{"route":"#/gitav/6.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:27:en2","title":"Gita 6.27, in another translation","body":"Verily, the supreme bliss comes to that Yogi, of perfectly tranquil mind, with passions quieted, Brahman-become, and freed from taint.","facts":[["Chapter","The Way of Meditation"],["Verse","27 of 47"]]},"gv-6-28":{"route":"#/gitav/6.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:28:en","title":"Bhagavad Gita 6.28","text":"युञ्जन्नेवं सदाऽऽत्मानं योगी विगतकल्मषः ।\nसुखेन ब्रह्मसंस्पर्शमत्यन्तं सुखमश्नुते ॥","lang":"sa","roman":"yuñjannevaṃ sadā’’tmānaṃ yogī vigatakalmaṣaḥ |\nsukhena brahmasaṃsparśamatyantaṃ sukhamaśnute ||","body":"The Yogî who thus, ever harmonising the self, hath put away sin, he easily enjoyeth the infinite bliss of contact with the Eternal.","facts":[["Chapter","The Way of Meditation"],["Verse","28 of 47"]]},"g2-6-28":{"route":"#/gitav/6.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:28:en2","title":"Gita 6.28, in another translation","body":"The Yogi freed from taint (of good and evil), constantly engaging the mind thus, with ease attains the infinite bliss of contact with Brahman.","facts":[["Chapter","The Way of Meditation"],["Verse","28 of 47"]]},"gv-6-29":{"route":"#/gitav/6.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:29:en","title":"Bhagavad Gita 6.29","text":"सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि ।\nईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः ॥","lang":"sa","roman":"sarvabhūtasthamātmānaṃ sarvabhūtāni cātmani |\nīkṣate yogayuktātmā sarvatra samadarśanaḥ ||","body":"The self, harmonised by yoga, seeth the Self abiding in all beings, all beings in the Self; everywhere he seeth the same.","facts":[["Chapter","The Way of Meditation"],["Verse","29 of 47"]]},"g2-6-29":{"route":"#/gitav/6.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:29:en2","title":"Gita 6.29, in another translation","body":"With the heart concentrated by Yoga, with the eye of evenness for all things, he beholds the Self in all beings and all beings in the Self.","facts":[["Chapter","The Way of Meditation"],["Verse","29 of 47"]]},"gv-6-30":{"route":"#/gitav/6.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:30:en","title":"Bhagavad Gita 6.30","text":"यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति ।\nतस्याहं न प्रणश्यामि स च मे न प्रणश्यति ॥","lang":"sa","roman":"yo māṃ paśyati sarvatra sarvaṃ ca mayi paśyati |\ntasyāhaṃ na praṇaśyāmi sa ca me na praṇaśyati ||","body":"He who seeth Me everywhere, and seeth everything in Me, of him will I never lose hold, and he shall never lose hold of Me.","facts":[["Chapter","The Way of Meditation"],["Verse","30 of 47"]]},"g2-6-30":{"route":"#/gitav/6.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:30:en2","title":"Gita 6.30, in another translation","body":"He who sees Me in all things, and sees all things in Me, he never becomes separated from Me, nor do I become separated from him.","facts":[["Chapter","The Way of Meditation"],["Verse","30 of 47"]]},"gv-6-31":{"route":"#/gitav/6.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:31:en","title":"Bhagavad Gita 6.31","text":"सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः ।\nसर्वथा वर्तमानोऽपि स योगी मयि वर्तते ॥","lang":"sa","roman":"sarvabhūtasthitaṃ yo māṃ bhajatyekatvamāsthitaḥ |\nsarvathā vartamāno’pi sa yogī mayi vartate ||","body":"He who, established in unity, worshippeth Me abiding in all beings, that Yogi liveth in Me, whatever his mode of living.","facts":[["Chapter","The Way of Meditation"],["Verse","31 of 47"]]},"g2-6-31":{"route":"#/gitav/6.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:31:en2","title":"Gita 6.31, in another translation","body":"He who being established in unity, worships Me, who am dwelling in all beings, whatever his mode of life, that Yogi abides in Me.","facts":[["Chapter","The Way of Meditation"],["Verse","31 of 47"]]},"gv-6-32":{"route":"#/gitav/6.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:32:en","title":"Bhagavad Gita 6.32","text":"आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन ।\nसुखं वा यदि वा दुःखं स योगी परमो मतः ॥","lang":"sa","roman":"ātmaupamyena sarvatra samaṃ paśyati yo’rjuna |\nsukhaṃ vā yadi vā duḥkhaṃ sa yogī paramo mataḥ ||","body":"He who, through the likeness of the Self, O Arjuna, seeth equality in everything, whether pleasant or painful, he is considered a perfect Yogî.","facts":[["Chapter","The Way of Meditation"],["Verse","32 of 47"]]},"g2-6-32":{"route":"#/gitav/6.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:32:en2","title":"Gita 6.32, in another translation","body":"He who judges of pleasure or pain everywhere, by the same standard as he applies to himself, that Yogi, O Arjuna, is regarded as the highest.","facts":[["Chapter","The Way of Meditation"],["Verse","32 of 47"]]},"gv-6-33":{"route":"#/gitav/6.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:33:en","title":"Bhagavad Gita 6.33","text":"योऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन ।\nएतस्याहं न पश्यामि चञ्चलत्वात् स्थितिं स्थिराम् ॥","lang":"sa","roman":"yo’yaṃ yogastvayā proktaḥ sāmyena madhusūdana |\netasyāhaṃ na paśyāmi cañcalatvāt sthitiṃ sthirām ||","body":"This yoga which Thou hast declared to be by equanimity, O Madhusûdana, I see not a stable foundation for it, owing to restlessness;","facts":[["Chapter","The Way of Meditation"],["Verse","33 of 47"]]},"g2-6-33":{"route":"#/gitav/6.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:33:en2","title":"Gita 6.33, in another translation","body":"This Yoga which has been taught by Thee, O slayer of Madhu, as characterised by evenness, I do not see (the possibility of) its lasting endurance, owing to restlessness (of the mind).","facts":[["Chapter","The Way of Meditation"],["Verse","33 of 47"]]},"gv-6-34":{"route":"#/gitav/6.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:34:en","title":"Bhagavad Gita 6.34","text":"चञ्चलं हि मनः कृष्ण प्रमाथि बलवद्दृढम् ।\nतस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम् ॥","lang":"sa","roman":"cañcalaṃ hi manaḥ kṛṣṇa pramāthi balavaddṛḍham |\ntasyāhaṃ nigrahaṃ manye vāyoriva suduṣkaram ||","body":"For the mind is verily restless, O Krishna; it is impetuous, strong and difficult to bend. I deem it as hard to curb as the wind.","facts":[["Chapter","The Way of Meditation"],["Verse","34 of 47"]]},"g2-6-34":{"route":"#/gitav/6.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:34:en2","title":"Gita 6.34, in another translation","body":"Verily, the mind, O Krishna, is restless, turbulent, strong, and unyielding;. I regard it quite as hard to achieve its control, as that of the wind.","facts":[["Chapter","The Way of Meditation"],["Verse","34 of 47"]]},"gv-6-35":{"route":"#/gitav/6.35","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:35:en","title":"Bhagavad Gita 6.35","text":"असंशयं महाबाहो मनो दुर्निग्रहं चलम् ।\nअभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते ॥","lang":"sa","roman":"asaṃśayaṃ mahābāho mano durnigrahaṃ calam |\nabhyāsena tu kaunteya vairāgyeṇa ca gṛhyate ||","body":"The Blessed Lord said: Without doubt, O mighty-armed, the mind is hard to curb and restless; but it may be curbed by constant practice and by dispassion.","facts":[["Chapter","The Way of Meditation"],["Verse","35 of 47"]]},"g2-6-35":{"route":"#/gitav/6.35","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:35:en2","title":"Gita 6.35, in another translation","body":"Without doubt, O mighty-armed, the mind is restless, and difficult to control; but through practice and renunciation, O son of Kunti, it may be governed.","facts":[["Chapter","The Way of Meditation"],["Verse","35 of 47"]]},"gv-6-36":{"route":"#/gitav/6.36","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:36:en","title":"Bhagavad Gita 6.36","text":"असंयतात्मना योगो दुष्प्राप इति मे मतिः ।\nवश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः ॥","lang":"sa","roman":"asaṃyatātmanā yogo duṣprāpa iti me matiḥ |\nvaśyātmanā tu yatatā śakyo’vāptumupāyataḥ ||","body":"Yoga is hard to attain, methinks, by a self that is uncontrolled; but by the Self -controlled it is attainable by properly directed energy.","facts":[["Chapter","The Way of Meditation"],["Verse","36 of 47"]]},"g2-6-36":{"route":"#/gitav/6.36","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:36:en2","title":"Gita 6.36, in another translation","body":"Yoga is hard to be attained by one of uncontrolled self: such is My conviction; but the self-controlled, striving by right means, can obtain it.","facts":[["Chapter","The Way of Meditation"],["Verse","36 of 47"]]},"gv-6-37":{"route":"#/gitav/6.37","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:37:en","title":"Bhagavad Gita 6.37","text":"अयतिः श्रद्धयोपेतो योगाच्चलितमानसः ।\nअप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति ॥","lang":"sa","roman":"ayatiḥ śraddhayopeto yogāccalitamānasaḥ |\naprāpya yogasaṃsiddhiṃ kāṃ gatiṃ kṛṣṇa gacchati ||","body":"Arjuna said: He who is unsubdued but who possesseth faith, with the mind wandering away from yoga, failing to attain perfection in yoga, what path doth he tread, O Krishna?","facts":[["Chapter","The Way of Meditation"],["Verse","37 of 47"]]},"g2-6-37":{"route":"#/gitav/6.37","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:37:en2","title":"Gita 6.37, in another translation","body":"Though possessed of Shraddhâ but unable to control himself, with the mind wandering away from Yoga, what end does one, failing to gain perfection in Yoga, meet, O Krishna?","facts":[["Chapter","The Way of Meditation"],["Verse","37 of 47"]]},"gv-6-38":{"route":"#/gitav/6.38","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:38:en","title":"Bhagavad Gita 6.38","text":"कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति ।\nअप्रतिष्ठो महाबाहो विमूढो ब्रह्मणः पथि ॥","lang":"sa","roman":"kaccinnobhayavibhraṣṭaśchinnābhramiva naśyati |\napratiṣṭho mahābāho vimūḍho brahmaṇaḥ pathi ||","body":"Fallen from both, is he destroyed like a rent cloud, unsteadfast, O mighty-armed, deluded in the path of the Eternal?","facts":[["Chapter","The Way of Meditation"],["Verse","38 of 47"]]},"g2-6-38":{"route":"#/gitav/6.38","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:38:en2","title":"Gita 6.38, in another translation","body":"Does he not, fallen from both, perish, without support, like a rent cloud, O mighty-armed, deluded in the path of Brahman?","facts":[["Chapter","The Way of Meditation"],["Verse","38 of 47"]]},"gv-6-39":{"route":"#/gitav/6.39","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:39:en","title":"Bhagavad Gita 6.39","text":"एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः ।\nत्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते ॥","lang":"sa","roman":"etanme saṃśayaṃ kṛṣṇa chettumarhasyaśeṣataḥ |\ntvadanyaḥ saṃśayasyāsya chettā na hyupapadyate ||","body":"Deign, O Krishna, to completely dispel this doubt of mine; for there is none to be found save Thyself able to destroy this doubt.","facts":[["Chapter","The Way of Meditation"],["Verse","39 of 47"]]},"g2-6-39":{"route":"#/gitav/6.39","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:39:en2","title":"Gita 6.39, in another translation","body":"This doubt of mine, O Krishna, Thou shouldst completely dispel; for it is not possible for any but Thee to dispel this doubt.","facts":[["Chapter","The Way of Meditation"],["Verse","39 of 47"]]},"gv-6-40":{"route":"#/gitav/6.40","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:40:en","title":"Bhagavad Gita 6.40","text":"पार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते ।\nनहि कल्याणकृत्कश्चिद्दुर्गतिं तात गच्छति ॥","lang":"sa","roman":"pārtha naiveha nāmutra vināśastasya vidyate |\nnahi kalyāṇakṛtkaściddurgatiṃ tāta gacchati ||","body":"The Blessed Lord said: O son of Prithâ, neither in this world nor in the life to come is there destruction for him; never doth any who worketh righteousness, O beloved, tread the path of woe.","facts":[["Chapter","The Way of Meditation"],["Verse","40 of 47"]]},"g2-6-40":{"route":"#/gitav/6.40","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:40:en2","title":"Gita 6.40, in another translation","body":"Verily, O son of Prithâ, there is destruction for him, neither here nor hereafter: for, the doer of good, O my son, never comes to grief.","facts":[["Chapter","The Way of Meditation"],["Verse","40 of 47"]]},"gv-6-41":{"route":"#/gitav/6.41","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:41:en","title":"Bhagavad Gita 6.41","text":"प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः ।\nशुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते ॥","lang":"sa","roman":"prāpya puṇyakṛtāṃ lokānuṣitvā śāśvatīḥ samāḥ |\nśucīnāṃ śrīmatāṃ gehe yogabhraṣṭo’bhijāyate ||","body":"Having attained to the worlds of the pure-doing, and having dwelt there for immemorial years, he who fell from yoga is reborn in a pure and blessed house;","facts":[["Chapter","The Way of Meditation"],["Verse","41 of 47"]]},"g2-6-41":{"route":"#/gitav/6.41","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:41:en2","title":"Gita 6.41, in another translation","body":"Having attained to the worlds of the righteous, and dwelling there for everlasting years, one fallen from Yoga reincarnates in the home of the pure and the prosperous.","facts":[["Chapter","The Way of Meditation"],["Verse","41 of 47"]]},"gv-6-42":{"route":"#/gitav/6.42","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:42:en","title":"Bhagavad Gita 6.42","text":"अथवा योगिनामेव कुले भवति धीमताम् ।\nएतद्धि दुर्लभतरं लोके जन्म यदीदृशम् ॥","lang":"sa","roman":"athavā yogināmeva kule bhavati dhīmatām |\netaddhi durlabhataraṃ loke janma yadīdṛśam ||","body":"Or he may even be born into a family of wise Yogîs; but such a birth as that is most difficult to obtain in this world.","facts":[["Chapter","The Way of Meditation"],["Verse","42 of 47"]]},"g2-6-42":{"route":"#/gitav/6.42","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:42:en2","title":"Gita 6.42, in another translation","body":"Or else he is born into a family of wise Yogis only; verily, a birth such as that is very rare to obtain in this world.","facts":[["Chapter","The Way of Meditation"],["Verse","42 of 47"]]},"gv-6-43":{"route":"#/gitav/6.43","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:43:en","title":"Bhagavad Gita 6.43","text":"तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम् ।\nयतते च ततो भूयः संसिद्धौ कुरुनन्दन ॥","lang":"sa","roman":"tatra taṃ buddhisaṃyogaṃ labhate paurvadehikam |\nyatate ca tato bhūyaḥ saṃsiddhau kurunandana ||","body":"There he recovereth the characteristics belonging to this former body, and with these he again laboureth for perfection, O joy of the Kurus.","facts":[["Chapter","The Way of Meditation"],["Verse","43 of 47"]]},"g2-6-43":{"route":"#/gitav/6.43","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:43:en2","title":"Gita 6.43, in another translation","body":"There he is united with the intelligence acquired in his former body, and strives more than before, for perfection, O son of the Kurus.","facts":[["Chapter","The Way of Meditation"],["Verse","43 of 47"]]},"gv-6-44":{"route":"#/gitav/6.44","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:44:en","title":"Bhagavad Gita 6.44","text":"पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः ।\nजिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते ॥","lang":"sa","roman":"pūrvābhyāsena tenaiva hriyate hyavaśo’pi saḥ |\njijñāsurapi yogasya śabdabrahmātivartate ||","body":"By that former practice he is irresistibly swept away. Only wishing to know yoga, even the seeker after yoga goeth beyond the Brâhmic world;","facts":[["Chapter","The Way of Meditation"],["Verse","44 of 47"]]},"g2-6-44":{"route":"#/gitav/6.44","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:44:en2","title":"Gita 6.44, in another translation","body":"By that previous practice alone, he is borne on in spite of himself. Even the enquirer after Yoga rises superior to the performer of Vedic actions.","facts":[["Chapter","The Way of Meditation"],["Verse","44 of 47"]]},"gv-6-45":{"route":"#/gitav/6.45","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:45:en","title":"Bhagavad Gita 6.45","text":"प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः ।\nअनेकजन्मसंसिद्धस्ततो याति परां गतिम् ॥","lang":"sa","roman":"prayatnādyatamānastu yogī saṃśuddhakilbiṣaḥ |\nanekajanmasaṃsiddhastato yāti parāṃ gatim ||","body":"But the Yogî, labouring with assiduity, purified from sin, fully perfected through manifold births, he reacheth the supreme goal.","facts":[["Chapter","The Way of Meditation"],["Verse","45 of 47"]]},"g2-6-45":{"route":"#/gitav/6.45","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:45:en2","title":"Gita 6.45, in another translation","body":"The Yogi, striving assiduously, purified of taint, gradually gaining perfection through many births, then reaches the highest goal.","facts":[["Chapter","The Way of Meditation"],["Verse","45 of 47"]]},"gv-6-46":{"route":"#/gitav/6.46","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:46:en","title":"Bhagavad Gita 6.46","text":"तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः ।\nकर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन ॥","lang":"sa","roman":"tapasvibhyo’dhiko yogī jñānibhyo’pi mato’dhikaḥ |\nkarmibhyaścādhiko yogī tasmādyogī bhavārjuna ||","body":"The Yogî is greater than the ascetics; he is thought to be greater than even the wise; the Yogî is greater than the men of action; therefore become thou a Yogî, O Arjuna!","facts":[["Chapter","The Way of Meditation"],["Verse","46 of 47"]]},"g2-6-46":{"route":"#/gitav/6.46","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:46:en2","title":"Gita 6.46, in another translation","body":"The Yogi is regarded as superior to those who practise asceticism, also to those who have obtained wisdom (through the Shâstras). He is also superior to the performers of action, (enjoined in the Vedas). Therefore, be thou a Yogi, O Arjuna!","facts":[["Chapter","The Way of Meditation"],["Verse","46 of 47"]]},"gv-6-47":{"route":"#/gitav/6.47","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:47:en","title":"Bhagavad Gita 6.47","text":"योगिनामपि सर्वेषां मद्गतेनान्तरात्मना ।\nश्रद्धावान्भजते यो मां स मे युक्ततमो मतः ॥","lang":"sa","roman":"yogināmapi sarveṣāṃ madgatenāntarātmanā |\nśraddhāvānbhajate yo māṃ sa me yuktatamo mataḥ ||","body":"And among all Yogîs, he who, full of faith, with the inner Self abiding in Me, adoreth Me, he is considered by Me to be the most completely harmonised.","facts":[["Chapter","The Way of Meditation"],["Verse","47 of 47"]]},"g2-6-47":{"route":"#/gitav/6.47","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 6 — The Way of Meditation","src":"gita:6:47:en2","title":"Gita 6.47, in another translation","body":"And of all Yogis, he who with the inner self merged in Me, with Shraddhâ devotes himself to Me, is considered by Me the most steadfast.","facts":[["Chapter","The Way of Meditation"],["Verse","47 of 47"]]},"gv-7-1":{"route":"#/gitav/7.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:1:en","title":"Bhagavad Gita 7.1","text":"मय्यासक्तमनाः पार्थ योगं युञ्जन्मदाश्रयः ।\nअसंशयं समग्रं मां यथा ज्ञास्यसि तच्छृणु ॥","lang":"sa","roman":"mayyāsaktamanāḥ pārtha yogaṃ yuñjanmadāśrayaḥ |\nasaṃśayaṃ samagraṃ māṃ yathā jñāsyasi tacchṛṇu ||","body":"The Blessed Lord said: With the mind clinging to me, O Pârtha, performing yoga, refuged in Me, how thou shalt without doubt know Me to the uttermost, that hear thou.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","1 of 30"]]},"g2-7-1":{"route":"#/gitav/7.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:1:en2","title":"Gita 7.1, in another translation","body":"With the mind intent on Me, O son of Prithâ, taking refuge in Me, and practising Yoga, how thou shalt without doubt know Me fully, that do thou hear.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","1 of 30"]]},"gv-7-2":{"route":"#/gitav/7.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:2:en","title":"Bhagavad Gita 7.2","text":"ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः ।\nयज्ज्ञात्वा नेह भूयोऽन्यज्ज्ञातव्यमवशिष्यते ॥","lang":"sa","roman":"jñānaṃ te’haṃ savijñānamidaṃ vakṣyāmyaśeṣataḥ |\nyajjñātvā neha bhūyo’nyajjñātavyamavaśiṣyate ||","body":"I will declare to thee this knowledge and wisdom in its completeness, which, having known, there is nothing more here needeth to be known.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","2 of 30"]]},"g2-7-2":{"route":"#/gitav/7.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:2:en2","title":"Gita 7.2, in another translation","body":"I shall tell you in full, of knowledge, speculative and practical, knowing which, nothing more here remains to be known.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","2 of 30"]]},"gv-7-3":{"route":"#/gitav/7.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:3:en","title":"Bhagavad Gita 7.3","text":"मनुष्याणां सहस्रेषु कश्चिद्यतति सिद्धये ।\nयततामपि सिद्धानां कश्चिन्मां वेत्ति तत्त्वतः ॥","lang":"sa","roman":"manuṣyāṇāṃ sahasreṣu kaścidyatati siddhaye |\nyatatāmapi siddhānāṃ kaścinmāṃ vetti tattvataḥ ||","body":"Among thousands of men scarce one striveth for perfection; of the successful strivers scarce one knoweth Me in essence.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","3 of 30"]]},"g2-7-3":{"route":"#/gitav/7.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:3:en2","title":"Gita 7.3, in another translation","body":"One, perchance, in thousands of men, strives for perfection; and one perchance, among the blessed ones, striving thus, knows Me in reality.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","3 of 30"]]},"gv-7-4":{"route":"#/gitav/7.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:4:en","title":"Bhagavad Gita 7.4","text":"भूमिरापोऽनलो वायुः खं मनो बुद्धिरेव च ।\nअहङ्कार इतीयं मे भिन्ना प्रकृतिरष्टधा ॥","lang":"sa","roman":"bhūmirāpo’nalo vāyuḥ khaṃ mano buddhireva ca |\nahaṅkāra itīyaṃ me bhinnā prakṛtiraṣṭadhā ||","body":"Earth, water, fire, air, ether, Mind, and Reason also and Egoism—these are the eightfold division of My nature.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","4 of 30"]]},"g2-7-4":{"route":"#/gitav/7.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:4:en2","title":"Gita 7.4, in another translation","body":"Bhumi (earth), Ap (water), Anala (fire), Vâyu (air), Kha (ether), mind, intellect, and egoism: thus is My Prakriti divided eight-fold.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","4 of 30"]]},"gv-7-5":{"route":"#/gitav/7.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:5:en","title":"Bhagavad Gita 7.5","text":"अपरेयमितस्त्वन्यां प्रकृतिं विद्धि मे पराम् ।\nजीवभूतां महाबाहो ययेदं धार्यते जगत् ॥","lang":"sa","roman":"apareyamitastvanyāṃ prakṛtiṃ viddhi me parām |\njīvabhūtāṃ mahābāho yayedaṃ dhāryate jagat ||","body":"This the inferior. Know My other nature, the higher, the life-element, O mighty-armed, by which the universe is upheld.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","5 of 30"]]},"g2-7-5":{"route":"#/gitav/7.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:5:en2","title":"Gita 7.5, in another translation","body":"This is the lower (Prakriti). But different from it, know thou, O mighty-armed, My higher Prakriti—the principle of self-consciousness, by which this universe is sustained.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","5 of 30"]]},"gv-7-6":{"route":"#/gitav/7.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:6:en","title":"Bhagavad Gita 7.6","text":"एतद्योनीनि भूतानि सर्वाणीत्युपधारय ।\nअहं कृत्स्नस्य जगतः प्रभवः प्रलयस्तथा ॥","lang":"sa","roman":"etadyonīni bhūtāni sarvāṇītyupadhāraya |\nahaṃ kṛtsnasya jagataḥ prabhavaḥ pralayastathā ||","body":"Know this to be the womb of all beings. I am the source of the forthgoing of the whole universe and likewise the place of its dissolving.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","6 of 30"]]},"g2-7-6":{"route":"#/gitav/7.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:6:en2","title":"Gita 7.6, in another translation","body":"Know that these (two Prakritis) are the womb of all beings. I am the origin and dissolution of the whole universe.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","6 of 30"]]},"gv-7-7":{"route":"#/gitav/7.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:7:en","title":"Bhagavad Gita 7.7","text":"मत्तः परतरं नान्यत्किञ्चिदस्ति धनञ्जय ।\nमयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव ॥","lang":"sa","roman":"mattaḥ parataraṃ nānyatkiñcidasti dhanañjaya |\nmayi sarvamidaṃ protaṃ sūtre maṇigaṇā iva ||","body":"There is naught whatsoever higher than I, O Dhananjaya. All this is threaded on Me, as rows of pearls on a string.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","7 of 30"]]},"g2-7-7":{"route":"#/gitav/7.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:7:en2","title":"Gita 7.7, in another translation","body":"Beyond Me, O Dhananjaya, there is naught. All this is strung in Me, as a row of jewels on a thread.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","7 of 30"]]},"gv-7-8":{"route":"#/gitav/7.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:8:en","title":"Bhagavad Gita 7.8","text":"रसोऽहमप्सु कौन्तेय प्रभास्मि शशिसूर्ययोः ।\nप्रणवः सर्ववेदेषु शब्दः खे पौरुषं नृषु ॥","lang":"sa","roman":"raso’hamapsu kaunteya prabhāsmi śaśisūryayoḥ |\npraṇavaḥ sarvavedeṣu śabdaḥ khe pauruṣaṃ nṛṣu ||","body":"I the sapidity in waters, O son of Kuntî, I the radiance in moon and sun; the Word of Power in all the Vedas, sound in ether, and virility in men;","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","8 of 30"]]},"g2-7-8":{"route":"#/gitav/7.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:8:en2","title":"Gita 7.8, in another translation","body":"I am the sapidity in waters, O son of Kunti; I, the radiance in the moon and the sun; I am the Om in all the Vedas, sound in Akâsha, and manhood in men.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","8 of 30"]]},"gv-7-9":{"route":"#/gitav/7.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:9:en","title":"Bhagavad Gita 7.9","text":"पुण्यो गन्धः पृथिव्यां च तेजश्चास्मि विभावसौ ।\nजीवनं सर्वभूतेषु तपश्चास्मि तपस्विषु ॥","lang":"sa","roman":"puṇyo gandhaḥ pṛthivyāṃ ca tejaścāsmi vibhāvasau |\njīvanaṃ sarvabhūteṣu tapaścāsmi tapasviṣu ||","body":"The pure fragrance of earths and the bril liance in fire am I; the life in all beings am I, and the austerity in ascetics.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","9 of 30"]]},"g2-7-9":{"route":"#/gitav/7.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:9:en2","title":"Gita 7.9, in another translation","body":"I am the sweet fragrance in earth, and the brilliance in fire am I; the life in all beings, and the austerity am I in ascetics.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","9 of 30"]]},"gv-7-10":{"route":"#/gitav/7.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:10:en","title":"Bhagavad Gita 7.10","text":"बीजं मां सर्वभूतानां विद्धि पार्थ सनातनम् ।\nबुद्धिर्बुद्धिमतामस्मि तेजस्तेजस्विनामहम् ॥","lang":"sa","roman":"bījaṃ māṃ sarvabhūtānāṃ viddhi pārtha sanātanam |\nbuddhirbuddhimatāmasmi tejastejasvināmaham ||","body":"Know Me, O Pârtha! as the eternal seed of all beings. I am the Reason of the Reason-endowed, the splendour of splendid things am I.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","10 of 30"]]},"g2-7-10":{"route":"#/gitav/7.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:10:en2","title":"Gita 7.10, in another translation","body":"Know Me, O son of Prithâ, as the eternal seed of all beings. I am the intellect of the intelligent, and the heroism of the heroic.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","10 of 30"]]},"gv-7-11":{"route":"#/gitav/7.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:11:en","title":"Bhagavad Gita 7.11","text":"बलं बलवतां चाहं कामरागविवर्जितम् ।\nधर्माविरुद्धो भूतेषु कामोऽस्मि भरतर्षभ ॥","lang":"sa","roman":"balaṃ balavatāṃ cāhaṃ kāmarāgavivarjitam |\ndharmāviruddho bhūteṣu kāmo’smi bharatarṣabha ||","body":"And I the strength of the strong, devoid of desire and passion. In beings I am desire not contrary to duty, O Lord of the Bharatas.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","11 of 30"]]},"g2-7-11":{"route":"#/gitav/7.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:11:en2","title":"Gita 7.11, in another translation","body":"Of the strong, I am the strength devoid of desire and attachment. I am, O bull among the Bhâratas, desire in beings, unopposed to Dharma.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","11 of 30"]]},"gv-7-12":{"route":"#/gitav/7.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:12:en","title":"Bhagavad Gita 7.12","text":"ये चैव सात्त्विका भावा राजसास्तामसाश्च ये ।\nमत्त एवेति तान्विद्धि नत्वहं तेषु ते मयि ॥","lang":"sa","roman":"ye caiva sāttvikā bhāvā rājasāstāmasāśca ye |\nmatta eveti tānviddhi natvahaṃ teṣu te mayi ||","body":"The natures that are harmonious, active, slothful, these know as from Me; not I in them, but they in me.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","12 of 30"]]},"g2-7-12":{"route":"#/gitav/7.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:12:en2","title":"Gita 7.12, in another translation","body":"And whatever states pertaining to Sattva, and those pertaining to Rajas, and to Tamas, know them to proceed from Me alone; still I am not in them, but they are in Me.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","12 of 30"]]},"gv-7-13":{"route":"#/gitav/7.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:13:en","title":"Bhagavad Gita 7.13","text":"त्रिभिर्गुणमयैर्भावैरेभिः सर्वमिदं जगत् ।\nमोहितं नाभिजानाति मामेभ्यः परमव्ययम् ॥","lang":"sa","roman":"tribhirguṇamayairbhāvairebhiḥ sarvamidaṃ jagat |\nmohitaṃ nābhijānāti māmebhyaḥ paramavyayam ||","body":"All this world, deluded by these natures made by the three qualities, knoweth not Me, above these, imperishable.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","13 of 30"]]},"g2-7-13":{"route":"#/gitav/7.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:13:en2","title":"Gita 7.13, in another translation","body":"Deluded by these states, the modifications of the three Gunas (of Prakriti), all this world does not know Me, beyond them, and immutable.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","13 of 30"]]},"gv-7-14":{"route":"#/gitav/7.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:14:en","title":"Bhagavad Gita 7.14","text":"दैवी ह्येषा गुणमयी मम माया दुरत्यया ।\nमामेव ये प्रपद्यन्ते मायामेतां तरन्ति ते ॥","lang":"sa","roman":"daivī hyeṣā guṇamayī mama māyā duratyayā |\nmāmeva ye prapadyante māyāmetāṃ taranti te ||","body":"This divine illusion of Mine, caused by the qualities, is hard to pierce; they who come to Me, they cross over this illusion.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","14 of 30"]]},"g2-7-14":{"route":"#/gitav/7.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:14:en2","title":"Gita 7.14, in another translation","body":"Verily, this divine illusion of Mine, constituted of the Gunas, is difficult to cross over; those who devote themselves to Me alone, cross over this illusion.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","14 of 30"]]},"gv-7-15":{"route":"#/gitav/7.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:15:en","title":"Bhagavad Gita 7.15","text":"न मां दुष्कृतिनो मूढाः प्रपद्यन्ते नराधमाः ।\nमाययापहृतज्ञाना आसुरं भावमाश्रिताः ॥","lang":"sa","roman":"na māṃ duṣkṛtino mūḍhāḥ prapadyante narādhamāḥ |\nmāyayāpahṛtajñānā āsuraṃ bhāvamāśritāḥ ||","body":"The evil-doing, the deluded, the vilest men, they come not to Me, they whose wisdom is destroyed by illusion, who have embraced the nature of demons.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","15 of 30"]]},"g2-7-15":{"route":"#/gitav/7.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:15:en2","title":"Gita 7.15, in another translation","body":"They do not devote themselves to Me,—the evil-doers, the deluded, the lowest of men, deprived of discrimination by Mâyâ, and following the way of the Asuras.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","15 of 30"]]},"gv-7-16":{"route":"#/gitav/7.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:16:en","title":"Bhagavad Gita 7.16","text":"चतुर्विधा भजन्ते मां जनाः सुकृतिनोऽर्जुन ।\nआर्तो जिज्ञासुरर्थार्थी ज्ञानी च भरतर्षभ ॥","lang":"sa","roman":"caturvidhā bhajante māṃ janāḥ sukṛtino’rjuna |\nārto jijñāsurarthārthī jñānī ca bharatarṣabha ||","body":"Fourfold in division are the righteous ones who worship me, O Arjuna; the suffering, the seeker for knowledge, the self-interested and the wise, O Lord of the Bhâratas.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","16 of 30"]]},"g2-7-16":{"route":"#/gitav/7.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:16:en2","title":"Gita 7.16, in another translation","body":"Four kinds of virtuous men worship Me, O Arjuna,—the distressed, the seeker of knowledge, the seeker of enjoyment, and the wise, O bull among the Bhâratas.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","16 of 30"]]},"gv-7-17":{"route":"#/gitav/7.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:17:en","title":"Bhagavad Gita 7.17","text":"तेषां ज्ञानी नित्ययुक्त एकभक्तिर्विशिष्यते ।\nप्रियो हि ज्ञानिनोऽत्यर्थमहं स च मम प्रियः ॥","lang":"sa","roman":"teṣāṃ jñānī nityayukta ekabhaktirviśiṣyate |\npriyo hi jñānino’tyarthamahaṃ sa ca mama priyaḥ ||","body":"Of these the wise, constantly harmonised, worshipping the One, is the best; I am supremely dear to the wise, and he is dear to Me.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","17 of 30"]]},"g2-7-17":{"route":"#/gitav/7.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:17:en2","title":"Gita 7.17, in another translation","body":"Of them, the wise man, ever-steadfast, (and fired) with devotion to the One, excels; for supremely dear am I to the wise, and he is dear to Me.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","17 of 30"]]},"gv-7-18":{"route":"#/gitav/7.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:18:en","title":"Bhagavad Gita 7.18","text":"उदाराः सर्व एवैते ज्ञानी त्वात्मैव मे मतम् ।\nआस्थितः स हि युक्तात्मा मामेवानुत्तमां गतिम् ॥","lang":"sa","roman":"udārāḥ sarva evaite jñānī tvātmaiva me matam |\nāsthitaḥ sa hi yuktātmā māmevānuttamāṃ gatim ||","body":"Noble are all these, but I hold the wise as verily Myself; he, Self united, is fixed on Me, the highest Path.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","18 of 30"]]},"g2-7-18":{"route":"#/gitav/7.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:18:en2","title":"Gita 7.18, in another translation","body":"Noble indeed are they all, but the wise man I regard as My very Self; for with the mind steadfast, he is established in Me alone, as the supreme goal.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","18 of 30"]]},"gv-7-19":{"route":"#/gitav/7.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:19:en","title":"Bhagavad Gita 7.19","text":"बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते ।\nवासुदेवः सर्वमिति स महात्मा सुदुर्लभः ॥","lang":"sa","roman":"bahūnāṃ janmanāmante jñānavānmāṃ prapadyate |\nvāsudevaḥ sarvamiti sa mahātmā sudurlabhaḥ ||","body":"At the close of many births the man full of wisdom cometh unto Me; \"Vâsudeva is all.\" saith he, the Mahâtmâ, very difficult to find.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","19 of 30"]]},"g2-7-19":{"route":"#/gitav/7.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:19:en2","title":"Gita 7.19, in another translation","body":"At the end of many births, the man of wisdom takes refuge in Me, realising that all this is Vâsudeva (the innermost Self). Very rare is that great soul.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","19 of 30"]]},"gv-7-20":{"route":"#/gitav/7.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:20:en","title":"Bhagavad Gita 7.20","text":"कामैस्तैस्तैर्हृतज्ञानाः प्रपद्यन्तेऽन्यदेवताः ।\nतं तं नियममास्थाय प्रकृत्या नियताः स्वया ॥","lang":"sa","roman":"kāmaistaistairhṛtajñānāḥ prapadyante’nyadevatāḥ |\ntaṃ taṃ niyamamāsthāya prakṛtyā niyatāḥ svayā ||","body":"They whose wisdom hath been rent away by desires go forth to other Shining Ones, resorting to various external observances, according to their own natures.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","20 of 30"]]},"g2-7-20":{"route":"#/gitav/7.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:20:en2","title":"Gita 7.20, in another translation","body":"Others again, deprived of discrimination by this or that desire, following this or that rite, devote themselves to other gods, led by their own natures.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","20 of 30"]]},"gv-7-21":{"route":"#/gitav/7.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:21:en","title":"Bhagavad Gita 7.21","text":"यो यो यां यां तनुं भक्तः श्रद्धयार्चितुमिच्छति ।\nतस्य तस्याचलां श्रद्धां तामेव विदधाम्यहम् ॥","lang":"sa","roman":"yo yo yāṃ yāṃ tanuṃ bhaktaḥ śraddhayārcitumicchati |\ntasya tasyācalāṃ śraddhāṃ tāmeva vidadhāmyaham ||","body":"Any devotee who seeketh to worship with faith any such aspect, I verily bestow the unswerving faith of that man.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","21 of 30"]]},"g2-7-21":{"route":"#/gitav/7.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:21:en2","title":"Gita 7.21, in another translation","body":"Whatsoever form any devotee seeks to worship with Shraddhâ,—that Shraddhâ of his do I make unwavering.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","21 of 30"]]},"gv-7-22":{"route":"#/gitav/7.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:22:en","title":"Bhagavad Gita 7.22","text":"स तया श्रद्धया युक्तस्तस्याराधनमीहते ।\nलभते च ततः कामान्मयैव विहितान् हि तान् ॥","lang":"sa","roman":"sa tayā śraddhayā yuktastasyārādhanamīhate |\nlabhate ca tataḥ kāmānmayaiva vihitān hi tān ||","body":"He endowed with that faith, seeketh the worship of such a one, and from him he obtaineth his desires, I verily decreeing the benefits;","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","22 of 30"]]},"g2-7-22":{"route":"#/gitav/7.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:22:en2","title":"Gita 7.22, in another translation","body":"Endued with that Shraddhâ, he engages in the worship of that, and from it, gains his desires,—these being verily dispensed by Me alone.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","22 of 30"]]},"gv-7-23":{"route":"#/gitav/7.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:23:en","title":"Bhagavad Gita 7.23","text":"अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम् ।\nदेवान्देवयजो यान्ति मद्भक्ता यान्ति मामपि ॥","lang":"sa","roman":"antavattu phalaṃ teṣāṃ tadbhavatyalpamedhasām |\ndevāndevayajo yānti madbhaktā yānti māmapi ||","body":"Finite indeed the fruit that belongeth to those who are of small intelligence. To the Shining Ones go the worshippers of the Shining Ones, but my devotees come unto Me.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","23 of 30"]]},"g2-7-23":{"route":"#/gitav/7.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:23:en2","title":"Gita 7.23, in another translation","body":"But the fruit (accruing) to these men of little understanding is limited. The worshippers of the Devas go to the Devas; My devotees too come to me.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","23 of 30"]]},"gv-7-24":{"route":"#/gitav/7.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:24:en","title":"Bhagavad Gita 7.24","text":"अव्यक्तं व्यक्तिमापन्नं मन्यन्ते मामबुद्धयः ।\nपरं भावमजानन्तो ममाव्ययमनुत्तमम् ॥","lang":"sa","roman":"avyaktaṃ vyaktimāpannaṃ manyante māmabuddhayaḥ |\nparaṃ bhāvamajānanto mamāvyayamanuttamam ||","body":"Those devoid of Reason think of Me, the unmanifest, as having manifestation, knowing not My supreme nature, imperishable, most excellent.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","24 of 30"]]},"g2-7-24":{"route":"#/gitav/7.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:24:en2","title":"Gita 7.24, in another translation","body":"The foolish regard Me, the un-manifested, as come into manifestation, not knowing My supreme state,—immutable and transcendental.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","24 of 30"]]},"gv-7-25":{"route":"#/gitav/7.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:25:en","title":"Bhagavad Gita 7.25","text":"नाहं प्रकाशः सर्वस्य योगमायासमावृतः ।\nमूढोऽयं नाभिजानाति लोको मामजमव्ययम् ॥","lang":"sa","roman":"nāhaṃ prakāśaḥ sarvasya yogamāyāsamāvṛtaḥ |\nmūḍho’yaṃ nābhijānāti loko māmajamavyayam ||","body":"Nor am I of all discovered, enveloped in My creation-illusion. This deluded world knoweth Me not, the unborn, the imperishable.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","25 of 30"]]},"g2-7-25":{"route":"#/gitav/7.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:25:en2","title":"Gita 7.25, in another translation","body":"Veiled by the illusion born of the congress of the Gunas, I am not manifest to all. This deluded world knows Me not, the Unborn, the Immutable.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","25 of 30"]]},"gv-7-26":{"route":"#/gitav/7.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:26:en","title":"Bhagavad Gita 7.26","text":"वेदाहं समतीतानि वर्तमानानि चार्जुन ।\nभविष्याणि च भूतानि मां तु वेद न कश्चन ॥","lang":"sa","roman":"vedāhaṃ samatītāni vartamānāni cārjuna |\nbhaviṣyāṇi ca bhūtāni māṃ tu veda na kaścana ||","body":"I know the beings that are past, that are present, that are to come, O Arjuna, but no one knoweth Me.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","26 of 30"]]},"g2-7-26":{"route":"#/gitav/7.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:26:en2","title":"Gita 7.26, in another translation","body":"I know, O Arjuna, the beings of the whole past, and the present, and the future, but Me none knoweth.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","26 of 30"]]},"gv-7-27":{"route":"#/gitav/7.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:27:en","title":"Bhagavad Gita 7.27","text":"इच्छाद्वेषसमुत्थेन द्वन्द्वमोहेन भारत ।\nसर्वभूतानि संमोहं सर्गे यान्ति परन्तप ॥","lang":"sa","roman":"icchādveṣasamutthena dvandvamohena bhārata |\nsarvabhūtāni saṃmohaṃ sarge yānti parantapa ||","body":"By the delusion of the pairs of opposites, sprung from attraction and repulsion, O Bhârata, all beings walk this universe wholly deluded, O Parantapa.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","27 of 30"]]},"g2-7-27":{"route":"#/gitav/7.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:27:en2","title":"Gita 7.27, in another translation","body":"By the delusion of the pairs of opposites, arising from desire and aversion, O descendant of Bharata, all beings fall into delusion at birth, O scorcher of foes.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","27 of 30"]]},"gv-7-28":{"route":"#/gitav/7.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:28:en","title":"Bhagavad Gita 7.28","text":"येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम् ।\nते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः ॥","lang":"sa","roman":"yeṣāṃ tvantagataṃ pāpaṃ janānāṃ puṇyakarmaṇām |\nte dvandvamohanirmuktā bhajante māṃ dṛḍhavratāḥ ||","body":"But those men of pure deeds, in whom sin is come to an end, they, freed from the delusive pairs of opposites, worship Me, steadfast in vows.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","28 of 30"]]},"g2-7-28":{"route":"#/gitav/7.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:28:en2","title":"Gita 7.28, in another translation","body":"Those men of virtuous deeds, whose sin has come to an end,—they, freed from the delusion of the pairs of opposites, worship Me with firm resolve.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","28 of 30"]]},"gv-7-29":{"route":"#/gitav/7.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:29:en","title":"Bhagavad Gita 7.29","text":"जरामरणमोक्षाय मामाश्रित्य यतन्ति ये ।\nते ब्रह्म तद्विदुः कृत्स्नमध्यात्मं कर्म चाखिलम् ॥","lang":"sa","roman":"jarāmaraṇamokṣāya māmāśritya yatanti ye |\nte brahma tadviduḥ kṛtsnamadhyātmaṃ karma cākhilam ||","body":"They who, refuged in Me, strive for liberation from birth and death, they know the Eternal, the whole Self -knowledge, and all action.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","29 of 30"]]},"g2-7-29":{"route":"#/gitav/7.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:29:en2","title":"Gita 7.29, in another translation","body":"Those who strive for freedom from old age and death, taking refuge in Me, they know. Brahman, the whole of Adhyâtma, and Karma in its entirety.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","29 of 30"]]},"gv-7-30":{"route":"#/gitav/7.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:30:en","title":"Bhagavad Gita 7.30","text":"साधिभूताधिदैवं मां साधियज्ञं च ये विदुः ।\nप्रयाणकालेऽपि च मां ते विदुर्युक्तचेतसः ॥","lang":"sa","roman":"sādhibhūtādhidaivaṃ māṃ sādhiyajñaṃ ca ye viduḥ |\nprayāṇakāle’pi ca māṃ te viduryuktacetasaḥ ||","body":"They who know Me as the knowledge of the elements, as that of the Shining Ones, and as that of the Sacrifice, they harmonised in mind, know Me verily even in the time of forthgoing.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","30 of 30"]]},"g2-7-30":{"route":"#/gitav/7.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 7 — The Way of Knowledge with Realisation","src":"gita:7:30:en2","title":"Gita 7.30, in another translation","body":"Those who know Me with the Adhibhuta, the Adhidaiva, and the Adhiyajna, (continue to) know Me even at the time of death, steadfast in mind.","facts":[["Chapter","The Way of Knowledge with Realisation"],["Verse","30 of 30"]]},"gv-8-1":{"route":"#/gitav/8.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:1:en","title":"Bhagavad Gita 8.1","text":"किं तद्ब्रह्म किमध्यात्मं किं कर्म पुरुषोत्तम ।\nअधिभूतं च किं प्रोक्तमधिदैवं किमुच्यते ॥","lang":"sa","roman":"kiṃ tadbrahma kimadhyātmaṃ kiṃ karma puruṣottama |\nadhibhūtaṃ ca kiṃ proktamadhidaivaṃ kimucyate ||","body":"Arjuna said: What is that Eternal, what Self -knowledge, what Action, O Purushottama? And what is declared to be the knowledge of the Elements, what is called the knowledge of the Shining Ones?","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","1 of 28"]]},"g2-8-1":{"route":"#/gitav/8.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:1:en2","title":"Gita 8.1, in another translation","body":"What is that Brahman, what is Adhyâtma, what is Karma, O best of Purushas? What is called Adhibhuta, and what Adhidaiva?","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","1 of 28"]]},"gv-8-2":{"route":"#/gitav/8.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:2:en","title":"Bhagavad Gita 8.2","text":"अधियज्ञः कथं कोऽत्र देहेऽस्मिन्मधुसूदन ।\nप्रयाणकाले च कथं ज्ञेयोऽसि नियतात्मभिः ॥","lang":"sa","roman":"adhiyajñaḥ kathaṃ ko’tra dehe’sminmadhusūdana |\nprayāṇakāle ca kathaṃ jñeyo’si niyatātmabhiḥ ||","body":"What is the knowledge of Sacrifice in this body, and how, O, Madhusûdana? And how, at the time of forthgoing art Thou known by the Self -controlled?","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","2 of 28"]]},"g2-8-2":{"route":"#/gitav/8.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:2:en2","title":"Gita 8.2, in another translation","body":"Who, and in what way, is Adhiyajna here in this body, O destroyer of Madhu? And how art Thou known at the time of death, by the self-controlled?","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","2 of 28"]]},"gv-8-3":{"route":"#/gitav/8.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:3:en","title":"Bhagavad Gita 8.3","text":"अक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते ।\nभूतभावोद्भवकरो विसर्गः कर्मसंज्ञितः ॥","lang":"sa","roman":"akṣaraṃ brahma paramaṃ svabhāvo’dhyātmamucyate |\nbhūtabhāvodbhavakaro visargaḥ karmasaṃjñitaḥ ||","body":"The Blessed Lord said: The indestructible, the supreme is the Eternal; His essential nature is called Self -knowledge; the emanation that causes the birth of beings is named Action;","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","3 of 28"]]},"g2-8-3":{"route":"#/gitav/8.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:3:en2","title":"Gita 8.3, in another translation","body":"The Imperishable is the Supreme Brahman. Its dwelling in each individual body is called Adhyâtma; the offering in sacrifice which causes the genesis and support of beings, is called Karma.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","3 of 28"]]},"gv-8-4":{"route":"#/gitav/8.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:4:en","title":"Bhagavad Gita 8.4","text":"अधिभूतं क्षरो भावः पुरुषश्चाधिदैवतम् ।\nअधियज्ञोऽहमेवात्र देहे देहभृतां वर ॥","lang":"sa","roman":"adhibhūtaṃ kṣaro bhāvaḥ puruṣaścādhidaivatam |\nadhiyajño’hamevātra dehe dehabhṛtāṃ vara ||","body":"Knowledge of the Elements concerns My perishable nature, and knowledge of the Shining Ones concerns the life-giving energy; the knowledge of Sacrifice tells of Me, as wearing the body, O best of living beings.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","4 of 28"]]},"g2-8-4":{"route":"#/gitav/8.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:4:en2","title":"Gita 8.4, in another translation","body":"The perishable adjunct is the Adhibhuta, and the Indweller is the Adhidaivata; I alone am the Adhiyajna here in this body, O best of the embodied.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","4 of 28"]]},"gv-8-5":{"route":"#/gitav/8.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:5:en","title":"Bhagavad Gita 8.5","text":"अन्तकाले च मामेव स्मरन्मुक्त्वा कलेवरम् ।\nयः प्रयाति स मद्भावं याति नास्त्यत्र संशयः ॥","lang":"sa","roman":"antakāle ca māmeva smaranmuktvā kalevaram |\nyaḥ prayāti sa madbhāvaṃ yāti nāstyatra saṃśayaḥ ||","body":"And he who, casting off the body, goeth forth thinking upon Me only at the time of the end, he entereth into My being: there is no doubt of that.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","5 of 28"]]},"g2-8-5":{"route":"#/gitav/8.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:5:en2","title":"Gita 8.5, in another translation","body":"And he, who at the time of death, meditating on Me alone, goes forth, leaving the body, attains My Being: there is no doubt about this.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","5 of 28"]]},"gv-8-6":{"route":"#/gitav/8.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:6:en","title":"Bhagavad Gita 8.6","text":"यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम् ।\nतं तमेवैति कौन्तेय सदा तद्भावभावितः ॥","lang":"sa","roman":"yaṃ yaṃ vāpi smaranbhāvaṃ tyajatyante kalevaram |\ntaṃ tamevaiti kaunteya sadā tadbhāvabhāvitaḥ ||","body":"Whosoever at the end abandoneth the body, thinking upon any being, to that being only he goeth, O Kaunteya, ever to that conformed in nature.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","6 of 28"]]},"g2-8-6":{"route":"#/gitav/8.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:6:en2","title":"Gita 8.6, in another translation","body":"Remembering whatever object, at the end, he leaves the body, that alone is reached by him, O son of Kunti, (because) of his constant thought of that object.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","6 of 28"]]},"gv-8-7":{"route":"#/gitav/8.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:7:en","title":"Bhagavad Gita 8.7","text":"तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च ।\nमय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयम् ॥","lang":"sa","roman":"tasmātsarveṣu kāleṣu māmanusmara yudhya ca |\nmayyarpitamanobuddhirmāmevaiṣyasyasaṃśayam ||","body":"Therefore at all times think upon Me only and fight. With mind and Reason set on Me, without doubt thou shalt come to Me.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","7 of 28"]]},"g2-8-7":{"route":"#/gitav/8.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:7:en2","title":"Gita 8.7, in another translation","body":"Therefore, at all times, constantly remember Me, and fight. With mind and intellect absorbed, in Me, thou shalt doubtless come to Me.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","7 of 28"]]},"gv-8-8":{"route":"#/gitav/8.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:8:en","title":"Bhagavad Gita 8.8","text":"अभ्यासयोगयुक्तेन चेतसा नान्यगामिना ।\nपरमं पुरुषं दिव्यं याति पार्थानुचिन्तयन् ॥","lang":"sa","roman":"abhyāsayogayuktena cetasā nānyagāminā |\nparamaṃ puruṣaṃ divyaṃ yāti pārthānucintayan ||","body":"With the mind not wandering after aught else, harmonised by continual practice, constantly meditating, O Pârtha, one goeth to the Spirit supreme, divine.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","8 of 28"]]},"g2-8-8":{"route":"#/gitav/8.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:8:en2","title":"Gita 8.8, in another translation","body":"With the mind not moving towards anything else, made steadfast by the method of habitual meditation, and dwelling on the Supreme, Resplendent Purusha, O son of Prithâ, one goes to Him.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","8 of 28"]]},"gv-8-9":{"route":"#/gitav/8.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:9:en","title":"Bhagavad Gita 8.9","text":"कविं पुराणमनुशासितार ।\nमणोरणीयांसमनुस्मरेद्यः ।\nसर्वस्य धातारमचिन्त्यरूप ।\nमादित्यवर्णं तमसः परस्तात् ॥","lang":"sa","roman":"kaviṃ purāṇamanuśāsitāra |\nmaṇoraṇīyāṃsamanusmaredyaḥ |\nsarvasya dhātāramacintyarūpa |\nmādityavarṇaṃ tamasaḥ parastāt ||","body":"He who thinketh upon the Ancient, the Omniscient, the All-Ruler, minuter than the minute, the supporter of all, of form unimaginable, refulgent as the sun beyond the darkness,","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","9 of 28"]]},"g2-8-9":{"route":"#/gitav/8.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:9:en2","title":"Gita 8.9, in another translation","body":"The Omniscient, the Ancient, the Overruler, minuter than an atom, the Sustainer of all, of form inconceivable, self-luminous like the sun, and beyond the darkness of Mâyâ—he who meditates on Him thus, at the time of death, full of devotion, with the mind unmoving, and also by the power of Yoga, fixing the whole Prâna betwixt the eye-brows, he goes to that Supreme, Resplendent Purusha.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","9 of 28"]]},"gv-8-10":{"route":"#/gitav/8.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:10:en","title":"Bhagavad Gita 8.10","text":"प्रयाणकाले मनसाऽचलेन ।\nभक्त्या युक्तो योगबलेन चैव ।\nभ्रुवोर्मध्ये प्राणमावेश्य सम्यक् ।\nस तं परं पुरुषमुपैति दिव्यम् ॥","lang":"sa","roman":"prayāṇakāle manasā’calena |\nbhaktyā yukto yogabalena caiva |\nbhruvormadhye prāṇamāveśya samyak |\nsa taṃ paraṃ puruṣamupaiti divyam ||","body":"In the time of forthgoing, with unshaken mind, fixed in devotion, by the power of yoga drawing together his life-breath in the centre of the two eyebrows, he goeth to this Spirit, supreme, divine.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","10 of 28"]]},"gv-8-11":{"route":"#/gitav/8.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:11:en","title":"Bhagavad Gita 8.11","text":"यदक्षरं वेदविदो वदन्ति ।\nविशन्ति यद्यतयो वीतरागाः ।\nयदिच्छन्तो ब्रह्मचर्यं चरन्ति ।\nतत्ते पदं संग्रहेण प्रवक्ष्ये ॥","lang":"sa","roman":"yadakṣaraṃ vedavido vadanti |\nviśanti yadyatayo vītarāgāḥ |\nyadicchanto brahmacaryaṃ caranti |\ntatte padaṃ saṃgraheṇa pravakṣye ||","body":"That which is declared indestructible by the Veda-knowers, that which the controlled and passion-free enter, that desiring which Brahmacharya is performed, that path I will declare to thee with brevity.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","11 of 28"]]},"g2-8-11":{"route":"#/gitav/8.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:11:en2","title":"Gita 8.11, in another translation","body":"What the knowers of the Veda speak of as Imperishable, what the self-controlled (Sannyâsins), freed from attachment enter, and to gain which goal they live the life of a Brahmachârin, that I shall declare unto thee in brief.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","11 of 28"]]},"gv-8-12":{"route":"#/gitav/8.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:12:en","title":"Bhagavad Gita 8.12","text":"सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च ।\nमूर्ध्न्याधायात्मनः प्राणमास्थितो योगधारणाम् ॥","lang":"sa","roman":"sarvadvārāṇi saṃyamya mano hṛdi nirudhya ca |\nmūrdhnyādhāyātmanaḥ prāṇamāsthito yogadhāraṇām ||","body":"All the gates closed, the mind confined in the heart, the life-breath fixed in his own head, concentrated by yoga,","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","12 of 28"]]},"g2-8-12":{"route":"#/gitav/8.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:12:en2","title":"Gita 8.12, in another translation","body":"Controlling all the senses, confining the mind in the heart, drawing the Prâna into the head, occupied in the practice of concentration, uttering the one-syllabled \"Om\"—the Brahman, and meditating on Me;—he who so departs, leaving the body, attains the Supreme Goal.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","12 of 28"]]},"gv-8-13":{"route":"#/gitav/8.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:13:en","title":"Bhagavad Gita 8.13","text":"ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन् ।\nयः प्रयाति त्यजन्देहं स याति परमां गतिम् ॥","lang":"sa","roman":"omityekākṣaraṃ brahma vyāharanmāmanusmaran |\nyaḥ prayāti tyajandehaṃ sa yāti paramāṃ gatim ||","body":"\"Aum!\" the one syllabled Eternal, reciting, thinking upon Me, he who goeth forth, abandoning the body, he goeth on the highest path.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","13 of 28"]]},"gv-8-14":{"route":"#/gitav/8.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:14:en","title":"Bhagavad Gita 8.14","text":"अनन्यचेताः सततं यो मां स्मरति नित्यशः ।\nतस्याहं सुलभः पार्थ नित्ययुक्तस्य योगिनः ॥","lang":"sa","roman":"ananyacetāḥ satataṃ yo māṃ smarati nityaśaḥ |\ntasyāhaṃ sulabhaḥ pārtha nityayuktasya yoginaḥ ||","body":"He who constantly thinketh upon Me, not thinking ever of another, of him I am easily reached, O Pârtha, of this ever-harmonised Yogî.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","14 of 28"]]},"g2-8-14":{"route":"#/gitav/8.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:14:en2","title":"Gita 8.14, in another translation","body":"I am easily attainable by that ever-steadfast Yogin who remembers Me constantly and daily, with a single mind, O son of Prithâ.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","14 of 28"]]},"gv-8-15":{"route":"#/gitav/8.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:15:en","title":"Bhagavad Gita 8.15","text":"मामुपेत्य पुनर्जन्म दुःखालयमशाश्वतम् ।\nनाप्नुवन्ति महात्मानः संसिद्धिं परमां गताः ॥","lang":"sa","roman":"māmupetya punarjanma duḥkhālayamaśāśvatam |\nnāpnuvanti mahātmānaḥ saṃsiddhiṃ paramāṃ gatāḥ ||","body":"Having come to Me, these Mahâtmâs come not again to birth, the place of pain, non-eternal; they have gone to the highest bliss.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","15 of 28"]]},"g2-8-15":{"route":"#/gitav/8.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:15:en2","title":"Gita 8.15, in another translation","body":"Reaching the highest perfection, and having attained Me, the great-souled ones are no more subject to re-birth—which is the home of pain, and ephemeral.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","15 of 28"]]},"gv-8-16":{"route":"#/gitav/8.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:16:en","title":"Bhagavad Gita 8.16","text":"आब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन ।\nमामुपेत्य तु कौन्तेय पुनर्जन्म न विद्यते ॥","lang":"sa","roman":"ābrahmabhuvanāllokāḥ punarāvartino’rjuna |\nmāmupetya tu kaunteya punarjanma na vidyate ||","body":"The worlds, beginning with the world of Brahmâ, they come and go, O Arjuna; but he who cometh unto Me, O Kaunteya, he knoweth birth no more.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","16 of 28"]]},"g2-8-16":{"route":"#/gitav/8.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:16:en2","title":"Gita 8.16, in another translation","body":"All the worlds, O Arjuna, including the realm of Brahmâ, are subject to return, but after attaining Me, O son of Kunti, there is no re-birth.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","16 of 28"]]},"gv-8-17":{"route":"#/gitav/8.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:17:en","title":"Bhagavad Gita 8.17","text":"सहस्रयुगपर्यन्तमहर्यद्ब्रह्मणो विदुः ।\nरात्रिं युगसहस्रान्तां तेऽहोरात्रविदो जनाः ॥","lang":"sa","roman":"sahasrayugaparyantamaharyadbrahmaṇo viduḥ |\nrātriṃ yugasahasrāntāṃ te’horātravido janāḥ ||","body":"The people who know the day of Brahmâ, a thousand ages in duration, and the night a thousand ages in ending, they know day and night.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","17 of 28"]]},"g2-8-17":{"route":"#/gitav/8.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:17:en2","title":"Gita 8.17, in another translation","body":"They who know (the true measure of) day and night, know the day of Brahmâ, which ends in a thousand Yugas, and the night which (also) ends in a thousand Yugas.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","17 of 28"]]},"gv-8-18":{"route":"#/gitav/8.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:18:en","title":"Bhagavad Gita 8.18","text":"अव्यक्ताद्व्यक्तयः सर्वाः प्रभवन्त्यहरागमे ।\nरात्र्यागमे प्रलीयन्ते तत्रैवाव्यक्तसंज्ञके ॥","lang":"sa","roman":"avyaktādvyaktayaḥ sarvāḥ prabhavantyaharāgame |\nrātryāgame pralīyante tatraivāvyaktasaṃjñake ||","body":"From the unmanifested all the manifested stream forth at the coming of day; at the coming of night they dissolve, even in That called the unmanifested.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","18 of 28"]]},"g2-8-18":{"route":"#/gitav/8.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:18:en2","title":"Gita 8.18, in another translation","body":"At the approach of (Brahmâ's) day, all manifestations proceed from the unmanifested state; at the approach of night, they merge verily into that alone, which is called the unmanifested.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","18 of 28"]]},"gv-8-19":{"route":"#/gitav/8.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:19:en","title":"Bhagavad Gita 8.19","text":"भूतग्रामः स एवायं भूत्वा भूत्वा प्रलीयते ।\nरात्र्यागमेऽवशः पार्थ प्रभवत्यहरागमे ॥","lang":"sa","roman":"bhūtagrāmaḥ sa evāyaṃ bhūtvā bhūtvā pralīyate |\nrātryāgame’vaśaḥ pārtha prabhavatyaharāgame ||","body":"This multitude of beings, going forth repeatedly, is dissolved at the coming of night: by ordination, O Pârtha, it streams forth at the coming of day.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","19 of 28"]]},"g2-8-19":{"route":"#/gitav/8.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:19:en2","title":"Gita 8.19, in another translation","body":"The very same multitude of beings (that existed in the preceding day of Brahmâ), being born again and again, merge, in spite of themselves, O son of Prithâ, (into the unmanifested), at the approach of night, and re-manifest at the approach of day.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","19 of 28"]]},"gv-8-20":{"route":"#/gitav/8.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:20:en","title":"Bhagavad Gita 8.20","text":"परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः ।\nयः स सर्वेषु भूतेषु नश्यत्सु न विनश्यति ॥","lang":"sa","roman":"parastasmāttu bhāvo’nyo’vyakto’vyaktātsanātanaḥ |\nyaḥ sa sarveṣu bhūteṣu naśyatsu na vinaśyati ||","body":"Therefore verily there existeth, higher than that unmanifested, another unmanifested, eternal, which in the destroying of all beings, is not destroyed.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","20 of 28"]]},"g2-8-20":{"route":"#/gitav/8.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:20:en2","title":"Gita 8.20, in another translation","body":"But beyond this unmanifested, there is that other Unmanifested, Eternal Existence—That which is not destroyed at the destruction of all beings.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","20 of 28"]]},"gv-8-21":{"route":"#/gitav/8.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:21:en","title":"Bhagavad Gita 8.21","text":"अव्यक्तोऽक्षर इत्युक्तस्तमाहुः परमां गतिम् ।\nयं प्राप्य न निवर्तन्ते तद्धाम परमं मम ॥","lang":"sa","roman":"avyakto’kṣara ityuktastamāhuḥ paramāṃ gatim |\nyaṃ prāpya na nivartante taddhāma paramaṃ mama ||","body":"That unmanifested, \"the Indestructible,\" It is called; It is named the highest Path. They who reach It return not. That is My supreme abode.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","21 of 28"]]},"g2-8-21":{"route":"#/gitav/8.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:21:en2","title":"Gita 8.21, in another translation","body":"What has been called Unmanifested and Imperishable, has been described as the Goal Supreme. That is My highest state, having attained which, there is no return.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","21 of 28"]]},"gv-8-22":{"route":"#/gitav/8.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:22:en","title":"Bhagavad Gita 8.22","text":"पुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया ।\nयस्यान्तःस्थानि भूतानि येन सर्वमिदं ततम् ॥","lang":"sa","roman":"puruṣaḥ sa paraḥ pārtha bhaktyā labhyastvananyayā |\nyasyāntaḥsthāni bhūtāni yena sarvamidaṃ tatam ||","body":"He, the highest Spirit, O Pârtha, may be reached by unswerving devotion to Him alone, in whom all beings abide, by whom all This is pervaded.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","22 of 28"]]},"g2-8-22":{"route":"#/gitav/8.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:22:en2","title":"Gita 8.22, in another translation","body":"And that Supreme Purusha is attainable, O son of Prithâ, by whole-souled devotion to Him alone, in Whom all beings dwell, and by Whom all this is pervaded.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","22 of 28"]]},"gv-8-23":{"route":"#/gitav/8.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:23:en","title":"Bhagavad Gita 8.23","text":"यत्र काले त्वनावृत्तिमावृत्तिं चैव योगिनः ।\nप्रयाता यान्ति तं कालं वक्ष्यामि भरतर्षभ ॥","lang":"sa","roman":"yatra kāle tvanāvṛttimāvṛttiṃ caiva yoginaḥ |\nprayātā yānti taṃ kālaṃ vakṣyāmi bharatarṣabha ||","body":"That time wherein going forth Yogîs return not, and also that wherein going forth they return, that time shall I declare to thee, O prince of the Bhâratas.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","23 of 28"]]},"g2-8-23":{"route":"#/gitav/8.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:23:en2","title":"Gita 8.23, in another translation","body":"Now I shall tell thee, O bull of the Bhâratas, of the time (path) travelling in which, the Yogis return, (and again of that, taking which) they do not return.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","23 of 28"]]},"gv-8-24":{"route":"#/gitav/8.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:24:en","title":"Bhagavad Gita 8.24","text":"अग्निर्ज्योतिरहः शुक्लः षण्मासा उत्तरायणम् ।\nतत्र प्रयाता गच्छन्ति ब्रह्म ब्रह्मविदो जनाः ॥","lang":"sa","roman":"agnirjyotirahaḥ śuklaḥ ṣaṇmāsā uttarāyaṇam |\ntatra prayātā gacchanti brahma brahmavido janāḥ ||","body":"Fire, light, day-time, the bright fortnight, the six months of the northern path—then, going forth, the men who know the Eternal go to the Eternal.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","24 of 28"]]},"g2-8-24":{"route":"#/gitav/8.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:24:en2","title":"Gita 8.24, in another translation","body":"Fire, flame, day-time, the bright fortnight, the six months of the Northern passage of the sun, taking this path, the knowers of Brahman go to Brahman.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","24 of 28"]]},"gv-8-25":{"route":"#/gitav/8.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:25:en","title":"Bhagavad Gita 8.25","text":"धूमो रात्रिस्तथा कृष्णः षण्मासा दक्षिणायनम् ।\nतत्र चान्द्रमसं ज्योतिर्योगी प्राप्य निवर्तते ॥","lang":"sa","roman":"dhūmo rātristathā kṛṣṇaḥ ṣaṇmāsā dakṣiṇāyanam |\ntatra cāndramasaṃ jyotiryogī prāpya nivartate ||","body":"Smoke, night-time, the dark fortnight also, the six months of the southern path—then the Yogî, obtaining the moonlight, returneth.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","25 of 28"]]},"g2-8-25":{"route":"#/gitav/8.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:25:en2","title":"Gita 8.25, in another translation","body":"Smoke, night-time, the dark fortnight, the six months of the Southern passage of the sun—taking this path the Yogi, attaining the lunar light, returns.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","25 of 28"]]},"gv-8-26":{"route":"#/gitav/8.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:26:en","title":"Bhagavad Gita 8.26","text":"शुक्लकृष्णे गती ह्येते जगतः शाश्वते मते ।\nएकया यात्यनावृत्तिमन्ययाऽऽवर्तते पुनः ॥","lang":"sa","roman":"śuklakṛṣṇe gatī hyete jagataḥ śāśvate mate |\nekayā yātyanāvṛttimanyayā’’vartate punaḥ ||","body":"Light and darkness, these are thought to be the world's everlasting paths; by the one he goeth who returneth not, by the other he who returneth again.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","26 of 28"]]},"g2-8-26":{"route":"#/gitav/8.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:26:en2","title":"Gita 8.26, in another translation","body":"Truly are these bright and dark paths of the world considered eternal: one leads to non-return; by the other, one returns.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","26 of 28"]]},"gv-8-27":{"route":"#/gitav/8.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:27:en","title":"Bhagavad Gita 8.27","text":"नैते सृती पार्थ जानन्योगी मुह्यति कश्चन ।\nतस्मात्सर्वेषु कालेषु योगयुक्तो भवार्जुन ॥","lang":"sa","roman":"naite sṛtī pārtha jānanyogī muhyati kaścana |\ntasmātsarveṣu kāleṣu yogayukto bhavārjuna ||","body":"Knowing these paths, O Pârtha, the Yogi is nowise perplexed. Therefore in all times be firm in yoga, O Arjuna.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","27 of 28"]]},"g2-8-27":{"route":"#/gitav/8.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:27:en2","title":"Gita 8.27, in another translation","body":"No Yogi, O son of Prithâ, is deluded after knowing these paths. Therefore, O Arjuna, be thou steadfast in Yoga, at all times.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","27 of 28"]]},"gv-8-28":{"route":"#/gitav/8.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:28:en","title":"Bhagavad Gita 8.28","text":"वेदेषु यज्ञेषु तपःसु चैव ।\nदानेषु यत्पुण्यफलं प्रदिष्टम् ।\nअत्येति तत्सर्वमिदं विदित्वा ।\nयोगी परं स्थानमुपैति चाद्यम् ॥","lang":"sa","roman":"vedeṣu yajñeṣu tapaḥsu caiva |\ndāneṣu yatpuṇyaphalaṃ pradiṣṭam |\natyeti tatsarvamidaṃ viditvā |\nyogī paraṃ sthānamupaiti cādyam ||","body":"The fruit of meritorious deeds, attached in the Vedas to sacrifices, to austerities, and also to almsgiving, the Yogî passeth all these by having known this, and goeth to the supreme and ancient Seat.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","28 of 28"]]},"g2-8-28":{"route":"#/gitav/8.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 8 — The Way to the Imperishable Brahman","src":"gita:8:28:en2","title":"Gita 8.28, in another translation","body":"Whatever meritorious effect is declared (in the Scriptures) to accrue from (the study of) the Vedas, (the performance of) Yajnas, (the practice of) austerities and gifts,—above all this rises the Yogi, having known this, and attains to the primeval, supreme Abode.","facts":[["Chapter","The Way to the Imperishable Brahman"],["Verse","28 of 28"]]},"gv-9-1":{"route":"#/gitav/9.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:1:en","title":"Bhagavad Gita 9.1","text":"इदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे ।\nज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥","lang":"sa","roman":"idaṃ tu te guhyatamaṃ pravakṣyāmyanasūyave |\njñānaṃ vijñānasahitaṃ yajjñātvā mokṣyase’śubhāt ||","body":"The Blessed Lord said: To thee, the uncarping, verily shall I declare this profoundest Secret, wisdom with knowledge combined, which, having known, thou shalt be freed from evil.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","1 of 34"]]},"g2-9-1":{"route":"#/gitav/9.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:1:en2","title":"Gita 9.1, in another translation","body":"To thee, who dost not carp, verily shall I now declare this, the most profound knowledge, united with realisation, having known which, thou shalt be free from evil (Samsâra).","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","1 of 34"]]},"gv-9-2":{"route":"#/gitav/9.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:2:en","title":"Bhagavad Gita 9.2","text":"राजविद्या राजगुह्यं पवित्रमिदमुत्तमम् ।\nप्रत्यक्षावगमं धर्म्यं सुसुखं कर्तुमव्ययम् ॥","lang":"sa","roman":"rājavidyā rājaguhyaṃ pavitramidamuttamam |\npratyakṣāvagamaṃ dharmyaṃ susukhaṃ kartumavyayam ||","body":"Kingly Science, kingly Secret, supreme Purifier, this; intuitional, according to righteousness, very easy to perform, imperishable.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","2 of 34"]]},"g2-9-2":{"route":"#/gitav/9.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:2:en2","title":"Gita 9.2, in another translation","body":"Of sciences, the highest; of profundities, the deepest; of purifiers, the supreme, is this; realisable by direct perception, endowed with (immense) merit, very easy to perform, and of an imperishable nature.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","2 of 34"]]},"gv-9-3":{"route":"#/gitav/9.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:3:en","title":"Bhagavad Gita 9.3","text":"अश्रद्दधानाः पुरुषा धर्मस्यास्य परन्तप ।\nअप्राप्य मां निवर्तन्ते मृत्युसंसारवर्त्मनि ॥","lang":"sa","roman":"aśraddadhānāḥ puruṣā dharmasyāsya parantapa |\naprāpya māṃ nivartante mṛtyusaṃsāravartmani ||","body":"Men without faith in this knowledge, O Parantapa, not reaching Me, return to the paths of this world of death.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","3 of 34"]]},"g2-9-3":{"route":"#/gitav/9.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:3:en2","title":"Gita 9.3, in another translation","body":"Persons without Shraddhâ for this Dharma, return, O scorcher of foes, without attaining Me, to the path of re-birth fraught with death.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","3 of 34"]]},"gv-9-4":{"route":"#/gitav/9.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:4:en","title":"Bhagavad Gita 9.4","text":"मया ततमिदं सर्वं जगदव्यक्तमूर्तिना ।\nमत्स्थानि सर्वभूतानि न चाहं तेष्ववस्थितः ॥","lang":"sa","roman":"mayā tatamidaṃ sarvaṃ jagadavyaktamūrtinā |\nmatsthāni sarvabhūtāni na cāhaṃ teṣvavasthitaḥ ||","body":"By Me all this world is pervaded in My unmanifested aspect; all beings have root in Me, I am not rooted in them.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","4 of 34"]]},"g2-9-4":{"route":"#/gitav/9.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:4:en2","title":"Gita 9.4, in another translation","body":"All this world is pervaded by me in My unmanifested form: all beings exist in Me, but I do not dwell in them.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","4 of 34"]]},"gv-9-5":{"route":"#/gitav/9.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:5:en","title":"Bhagavad Gita 9.5","text":"न च मत्स्थानि भूतानि पश्य मे योगमैश्वरम् ।\nभूतभृन्न च भूतस्थो ममात्मा भूतभावनः ॥","lang":"sa","roman":"na ca matsthāni bhūtāni paśya me yogamaiśvaram |\nbhūtabhṛnna ca bhūtastho mamātmā bhūtabhāvanaḥ ||","body":"Nor have beings root in Me; behold My sovereign Yoga! The support of beings, yet not rooted in beings, My Self their efficient cause.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","5 of 34"]]},"g2-9-5":{"route":"#/gitav/9.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:5:en2","title":"Gita 9.5, in another translation","body":"Nor do beings exist in Me (in reality), behold My Divine Yoga! Bringing forth and supporting the beings, My Self does not dwell in them.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","5 of 34"]]},"gv-9-6":{"route":"#/gitav/9.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:6:en","title":"Bhagavad Gita 9.6","text":"यथाऽऽकाशस्थितो नित्यं वायुः सर्वत्रगो महान् ।\nतथा सर्वाणि भूतानि मत्स्थानीत्युपधारय ॥","lang":"sa","roman":"yathā’’kāśasthito nityaṃ vāyuḥ sarvatrago mahān |\ntathā sarvāṇi bhūtāni matsthānītyupadhāraya ||","body":"As the mighty air everywhere moving is rooted in the Ether, so all beings rest rooted in Me—thus know thou.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","6 of 34"]]},"g2-9-6":{"route":"#/gitav/9.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:6:en2","title":"Gita 9.6, in another translation","body":"As the mighty wind, moving always everywhere, rests ever in the Akâsha, know thou, that even so do all beings rest in Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","6 of 34"]]},"gv-9-7":{"route":"#/gitav/9.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:7:en","title":"Bhagavad Gita 9.7","text":"सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम् ।\nकल्पक्षये पुनस्तानि कल्पादौ विसृजाम्यहम् ॥","lang":"sa","roman":"sarvabhūtāni kaunteya prakṛtiṃ yānti māmikām |\nkalpakṣaye punastāni kalpādau visṛjāmyaham ||","body":"All beings, O Kaunteya, enter my lower nature at the end of a world-age; at the beginning of a world-age again I emanate them.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","7 of 34"]]},"g2-9-7":{"route":"#/gitav/9.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:7:en2","title":"Gita 9.7, in another translation","body":"At the end of a Kalpa, O son of Kunti, all beings go back to My Prakriti: at the beginning of (another) Kalpa, I send them forth again.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","7 of 34"]]},"gv-9-8":{"route":"#/gitav/9.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:8:en","title":"Bhagavad Gita 9.8","text":"प्रकृतिं स्वामवष्टभ्य विसृजामि पुनः पुनः ।\nभूतग्राममिमं कृत्स्नमवशं प्रकृतेर्वशात् ॥","lang":"sa","roman":"prakṛtiṃ svāmavaṣṭabhya visṛjāmi punaḥ punaḥ |\nbhūtagrāmamimaṃ kṛtsnamavaśaṃ prakṛtervaśāt ||","body":"Hidden in Nature, which is mine own, I emanate again and again all this multitude of beings, helpless, by the force of Nature.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","8 of 34"]]},"g2-9-8":{"route":"#/gitav/9.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:8:en2","title":"Gita 9.8, in another translation","body":"Animating My Prakriti, I project again and again this whole multitude of beings, helpless under the sway of Prakriti.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","8 of 34"]]},"gv-9-9":{"route":"#/gitav/9.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:9:en","title":"Bhagavad Gita 9.9","text":"न च मां तानि कर्माणि निबध्नन्ति धनञ्जय ।\nउदासीनवदासीनमसक्तं तेषु कर्मसु ॥","lang":"sa","roman":"na ca māṃ tāni karmāṇi nibadhnanti dhanañjaya |\nudāsīnavadāsīnamasaktaṃ teṣu karmasu ||","body":"Nor do these works bind me, O Dhananjaya, enthroned on high unattached to actions.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","9 of 34"]]},"g2-9-9":{"route":"#/gitav/9.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:9:en2","title":"Gita 9.9, in another translation","body":"These acts do not bind Me, sitting as one neutral, unattached to them, O Dhananjaya.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","9 of 34"]]},"gv-9-10":{"route":"#/gitav/9.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:10:en","title":"Bhagavad Gita 9.10","text":"मयाऽध्यक्षेण प्रकृतिः सूयते सचराचरम् ।\nहेतुनाऽनेन कौन्तेय जगद्विपरिवर्तते ॥","lang":"sa","roman":"mayā’dhyakṣeṇa prakṛtiḥ sūyate sacarācaram |\nhetunā’nena kaunteya jagadviparivartate ||","body":"Under Me as supervisor, Nature sends forth the moving and unmoving: because of this, O Kaunteya, the universe revolves.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","10 of 34"]]},"g2-9-10":{"route":"#/gitav/9.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:10:en2","title":"Gita 9.10, in another translation","body":"By reason of My proximity, Prakriti produces all this, the moving and the unmoving; the world wheels round and round, O son of Kunti, because of this.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","10 of 34"]]},"gv-9-11":{"route":"#/gitav/9.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:11:en","title":"Bhagavad Gita 9.11","text":"अवजानन्ति मां मूढा मानुषीं तनुमाश्रितम् ।\nपरं भावमजानन्तो मम भूतमहेश्वरम् ॥","lang":"sa","roman":"avajānanti māṃ mūḍhā mānuṣīṃ tanumāśritam |\nparaṃ bhāvamajānanto mama bhūtamaheśvaram ||","body":"The foolish disregard Me, when clad in human semblance, ignorant of My supreme nature, the great Lord of beings;","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","11 of 34"]]},"g2-9-11":{"route":"#/gitav/9.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:11:en2","title":"Gita 9.11, in another translation","body":"Unaware of My higher state, as the great Lord of beings, fools disregard Me, dwelling in the human form.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","11 of 34"]]},"gv-9-12":{"route":"#/gitav/9.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:12:en","title":"Bhagavad Gita 9.12","text":"मोघाशा मोघकर्माणो मोघज्ञाना विचेतसः ।\nराक्षसीमासुरीं चैव प्रकृतिं मोहिनीं श्रिताः ॥","lang":"sa","roman":"moghāśā moghakarmāṇo moghajñānā vicetasaḥ |\nrākṣasīmāsurīṃ caiva prakṛtiṃ mohinīṃ śritāḥ ||","body":"Empty of hope, empty of deeds, empty of wisdom, senseless, partaking of the deceitful, brutal and demoniacal nature.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","12 of 34"]]},"g2-9-12":{"route":"#/gitav/9.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:12:en2","title":"Gita 9.12, in another translation","body":"Of vain hopes, of vain works, of vain knowledge, and senseless, they verily are possessed of the delusive nature of Râkshasas and Asuras.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","12 of 34"]]},"gv-9-13":{"route":"#/gitav/9.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:13:en","title":"Bhagavad Gita 9.13","text":"महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः ।\nभजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम् ॥","lang":"sa","roman":"mahātmānastu māṃ pārtha daivīṃ prakṛtimāśritāḥ |\nbhajantyananyamanaso jñātvā bhūtādimavyayam ||","body":"Verily the Mahâtmâs, O Partha, partaking of My divine nature, worship with unwavering mind, having known Me, the imperishable source of beings.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","13 of 34"]]},"g2-9-13":{"route":"#/gitav/9.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:13:en2","title":"Gita 9.13, in another translation","body":"But the great-souled ones, O son of Prithâ, possessed of the Divine Prakriti, knowing Me to be the origin of beings, and immutable, worship Me with a single mind.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","13 of 34"]]},"gv-9-14":{"route":"#/gitav/9.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:14:en","title":"Bhagavad Gita 9.14","text":"सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः ।\nनमस्यन्तश्च मां भक्त्या नित्ययुक्ता उपासते ॥","lang":"sa","roman":"satataṃ kīrtayanto māṃ yatantaśca dṛḍhavratāḥ |\nnamasyantaśca māṃ bhaktyā nityayuktā upāsate ||","body":"Always magnifying Me, strenuous, firm in vows, prostrating themselves before Me, they worship Me with devotion ever harmonised.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","14 of 34"]]},"g2-9-14":{"route":"#/gitav/9.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:14:en2","title":"Gita 9.14, in another translation","body":"Glorifying Me always and striving with firm resolve, bowing down to Me in devotion, always steadfast, they worship Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","14 of 34"]]},"gv-9-15":{"route":"#/gitav/9.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:15:en","title":"Bhagavad Gita 9.15","text":"ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते ।\nएकत्वेन पृथक्त्वेन बहुधा विश्वतोमुखम् ॥","lang":"sa","roman":"jñānayajñena cāpyanye yajanto māmupāsate |\nekatvena pṛthaktvena bahudhā viśvatomukham ||","body":"Others also, sacrificing with the sacrifice of wisdom, worship Me as the One and the Manifold everywhere present.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","15 of 34"]]},"g2-9-15":{"route":"#/gitav/9.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:15:en2","title":"Gita 9.15, in another translation","body":"Others, too, sacrificing by the Yajna of knowledge ( i.e. , seeing the Self in all), worship Me the All-Formed, as one, as distinct, as manifold.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","15 of 34"]]},"gv-9-16":{"route":"#/gitav/9.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:16:en","title":"Bhagavad Gita 9.16","text":"अहं क्रतुरहं यज्ञः स्वधाऽहमहमौषधम् ।\nमंत्रोऽहमहमेवाज्यमहमग्निरहं हुतम् ॥","lang":"sa","roman":"ahaṃ kraturahaṃ yajñaḥ svadhā’hamahamauṣadham |\nmaṃtro’hamahamevājyamahamagnirahaṃ hutam ||","body":"I the ablation; I the sacrifice; I the ancestral offering; I the fire-giving herb; the mantram I; I also the butter; I the fire; the burnt-offering I;","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","16 of 34"]]},"g2-9-16":{"route":"#/gitav/9.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:16:en2","title":"Gita 9.16, in another translation","body":"I am the Kratu, I the Yajna, I the Svadhâ, I the Aushadham, I the Mantra, I the Ajyam, I the fire, and I the oblation.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","16 of 34"]]},"gv-9-17":{"route":"#/gitav/9.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:17:en","title":"Bhagavad Gita 9.17","text":"पिताऽहमस्य जगतो माता धाता पितामहः ।\nवेद्यं पवित्रमोंकार ऋक् साम यजुरेव च ॥","lang":"sa","roman":"pitā’hamasya jagato mātā dhātā pitāmahaḥ |\nvedyaṃ pavitramoṃkāra ṛk sāma yajureva ca ||","body":"I the Father of this universe, the Mother, the Supporter, the Grandsire, the Holy one to be known, the Word of Power, and also the Rik, Sâma, and Yajur,","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","17 of 34"]]},"g2-9-17":{"route":"#/gitav/9.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:17:en2","title":"Gita 9.17, in another translation","body":"I am the Father of this world, the Mother, the Sustainer, the Grandfather; the Purifier, the (one) thing to be known, (the syllable) Om, and also the Rik, Sâman and Yajus.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","17 of 34"]]},"gv-9-18":{"route":"#/gitav/9.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:18:en","title":"Bhagavad Gita 9.18","text":"गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत् ।\nप्रभवः प्रलयः स्थानं निधानं बीजमव्ययम् ॥","lang":"sa","roman":"gatirbhartā prabhuḥ sākṣī nivāsaḥ śaraṇaṃ suhṛt |\nprabhavaḥ pralayaḥ sthānaṃ nidhānaṃ bījamavyayam ||","body":"The Path, Husband, Lord, Witness, Abode, Shelter, Lover, Origin, Dissolution, Foundation, house, Seed imperishable.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","18 of 34"]]},"g2-9-18":{"route":"#/gitav/9.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:18:en2","title":"Gita 9.18, in another translation","body":"The Goal, the Supporter, the Lord, the Witness, the Abode, the Refuge, the Friend, the Origin, the Dissolution, the Substratum, the Storehouse, the Seed immutable.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","18 of 34"]]},"gv-9-19":{"route":"#/gitav/9.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:19:en","title":"Bhagavad Gita 9.19","text":"तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च ।\nअमृतं चैव मृत्युश्च सदसच्चाहमर्जुन ॥","lang":"sa","roman":"tapāmyahamahaṃ varṣaṃ nigṛhṇāmyutsṛjāmi ca |\namṛtaṃ caiva mṛtyuśca sadasaccāhamarjuna ||","body":"I give heat; I hold back and send forth the rain; immortality and also death, being and non-being am I, Arjuna.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","19 of 34"]]},"g2-9-19":{"route":"#/gitav/9.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:19:en2","title":"Gita 9.19, in another translation","body":"(As sun) I give heat: I withhold and send forth rain; I am immortality and also death; being and non-being am I, O Arjuna!","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","19 of 34"]]},"gv-9-20":{"route":"#/gitav/9.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:20:en","title":"Bhagavad Gita 9.20","text":"त्रैविद्या मां सोमपाः पूतपापा ।\nयज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते ।\nते पुण्यमासाद्य सुरेन्द्रलोक ।\nमश्नन्ति दिव्यान्दिवि देवभोगान् ॥","lang":"sa","roman":"traividyā māṃ somapāḥ pūtapāpā |\nyajñairiṣṭvā svargatiṃ prārthayante |\nte puṇyamāsādya surendraloka |\nmaśnanti divyāndivi devabhogān ||","body":"The knowers of the three, the Soma-drinkers, the purified from sin, worshipping Me with sacrifice, pray of Me the way to heaven; they, ascending to the holy world of the Ruler of the Shining Ones, eat in heaven the divine feasts of the Shining Ones.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","20 of 34"]]},"g2-9-20":{"route":"#/gitav/9.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:20:en2","title":"Gita 9.20, in another translation","body":"The knowers of the three Vedas, worshipping Me by Yajna, drinking the Soma, and (thus) being purified from sin, pray for passage to heaven; reaching the holy world of the Lord of the Devas, they enjoy in heaven the divine pleasures of the Devas.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","20 of 34"]]},"gv-9-21":{"route":"#/gitav/9.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:21:en","title":"Bhagavad Gita 9.21","text":"ते तं भुक्त्वा स्वर्गलोकं विशालं ।\nक्षीणे पुण्ये मर्त्यलोकं विशन्ति ।\nएवं त्रयीधर्ममनुप्रपन्ना ।\nगतागतं कामकामा लभन्ते ॥","lang":"sa","roman":"te taṃ bhuktvā svargalokaṃ viśālaṃ |\nkṣīṇe puṇye martyalokaṃ viśanti |\nevaṃ trayīdharmamanuprapannā |\ngatāgataṃ kāmakāmā labhante ||","body":"They, having enjoyed the spacious heaven-world, their holiness withered, come back to this world of death. Following the virtues enjoined by the three, desiring desires, they obtain the transitory.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","21 of 34"]]},"g2-9-21":{"route":"#/gitav/9.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:21:en2","title":"Gita 9.21, in another translation","body":"Having enjoyed the vast Swarga-world, they enter the mortal world, on the exhaustion of their merit: Thus, abiding by the injunctions of the three (Vedas), desiring desires, they (constantly) come and go.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","21 of 34"]]},"gv-9-22":{"route":"#/gitav/9.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:22:en","title":"Bhagavad Gita 9.22","text":"अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते ।\nतेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम् ॥","lang":"sa","roman":"ananyāścintayanto māṃ ye janāḥ paryupāsate |\nteṣāṃ nityābhiyuktānāṃ yogakṣemaṃ vahāmyaham ||","body":"To those men who worship Me alone thinking of no other, to those ever harmonious, I bring full security.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","22 of 34"]]},"g2-9-22":{"route":"#/gitav/9.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:22:en2","title":"Gita 9.22, in another translation","body":"Persons who, meditating on Me as non-separate, worship Me in all beings, to them thus ever jealously engaged, I carry what they lack and preserve what they already have.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","22 of 34"]]},"gv-9-23":{"route":"#/gitav/9.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:23:en","title":"Bhagavad Gita 9.23","text":"येऽप्यन्यदेवता भक्ता यजन्ते श्रद्धयाऽन्विताः ।\nतेऽपि मामेव कौन्तेय यजन्त्यविधिपूर्वकम् ॥","lang":"sa","roman":"ye’pyanyadevatā bhaktā yajante śraddhayā’nvitāḥ |\nte’pi māmeva kaunteya yajantyavidhipūrvakam ||","body":"Even the devotees of other Shining Ones, who worship full of faith, they also worship Me, O son of Kuntî, though contrary to the ancient rule.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","23 of 34"]]},"g2-9-23":{"route":"#/gitav/9.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:23:en2","title":"Gita 9.23, in another translation","body":"Even those devotees, who endued with Shraddhâ, worship other gods, they too worship Me alone, O son of Kunti, (but) by the wrong method.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","23 of 34"]]},"gv-9-24":{"route":"#/gitav/9.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:24:en","title":"Bhagavad Gita 9.24","text":"अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च ।\nन तु मामभिजानन्ति तत्त्वेनातश्च्यवन्ति ते ॥","lang":"sa","roman":"ahaṃ hi sarvayajñānāṃ bhoktā ca prabhureva ca |\nna tu māmabhijānanti tattvenātaścyavanti te ||","body":"I am indeed the enjoyer of all sacrifices and also the Lord, but they know Me not in Essence, and hence they fall.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","24 of 34"]]},"g2-9-24":{"route":"#/gitav/9.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:24:en2","title":"Gita 9.24, in another translation","body":"For I alone am the Enjoyer, and Lord of all Yajnas; but because they do not know Me in reality, they return, (to the mortal world).","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","24 of 34"]]},"gv-9-25":{"route":"#/gitav/9.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:25:en","title":"Bhagavad Gita 9.25","text":"यान्ति देवव्रता देवान् पितॄन्यान्ति पितृव्रताः ।\nभूतानि यान्ति भूतेज्या यान्ति मद्याजिनोऽपि माम् ॥","lang":"sa","roman":"yānti devavratā devān pitṝnyānti pitṛvratāḥ |\nbhūtāni yānti bhūtejyā yānti madyājino’pi mām ||","body":"They who worship the Shining Ones go to the Shining Ones; to the Ancestors go the Ancestor-worshippers; to the Elements go those who sacrifice to Elementals; but My worshippers come unto Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","25 of 34"]]},"g2-9-25":{"route":"#/gitav/9.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:25:en2","title":"Gita 9.25, in another translation","body":"Votaries of the Devas go to the Devas; to the Pitris, go their votaries; to the Bhutas, go the Bhuta worshippers; My votaries too come unto Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","25 of 34"]]},"gv-9-26":{"route":"#/gitav/9.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:26:en","title":"Bhagavad Gita 9.26","text":"पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति ।\nतदहं भक्त्युपहृतमश्नामि प्रयतात्मनः ॥","lang":"sa","roman":"patraṃ puṣpaṃ phalaṃ toyaṃ yo me bhaktyā prayacchati |\ntadahaṃ bhaktyupahṛtamaśnāmi prayatātmanaḥ ||","body":"He who offereth to Me with devotion a leaf, a flower, a fruit, water, that I accept from the striving self, offered as it is with devotion.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","26 of 34"]]},"g2-9-26":{"route":"#/gitav/9.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:26:en2","title":"Gita 9.26, in another translation","body":"Whoever with devotion offers Me a leaf, a flower, a fruit, or water, that I accept—the devout gift of the pure-minded.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","26 of 34"]]},"gv-9-27":{"route":"#/gitav/9.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:27:en","title":"Bhagavad Gita 9.27","text":"यत्करोषि यदश्नासि यज्जुहोषि ददासि यत् ।\nयत्तपस्यसि कौन्तेय तत्कुरुष्व मदर्पणम् ॥","lang":"sa","roman":"yatkaroṣi yadaśnāsi yajjuhoṣi dadāsi yat |\nyattapasyasi kaunteya tatkuruṣva madarpaṇam ||","body":"Whatsoever thou doest, whatsoever thou eatest, whatsoever thou offerest, whatsoever thou givest, whatsoever thou doest of austerity, O Kaunteya, do thou that as an offering unto Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","27 of 34"]]},"g2-9-27":{"route":"#/gitav/9.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:27:en2","title":"Gita 9.27, in another translation","body":"Whatever thou doest, whatever thou eatest, whatever thou offerest in sacrifice, whatever thou givest away, whatever austerity thou practisest, O son of Kunti, do that as an offering unto Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","27 of 34"]]},"gv-9-28":{"route":"#/gitav/9.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:28:en","title":"Bhagavad Gita 9.28","text":"शुभाशुभफलैरेवं मोक्ष्यसे कर्मबन्धनैः ।\nसंन्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि ॥","lang":"sa","roman":"śubhāśubhaphalairevaṃ mokṣyase karmabandhanaiḥ |\nsaṃnyāsayogayuktātmā vimukto māmupaiṣyasi ||","body":"Thus shalt thou be liberated from the bonds of action, yielding good and evil fruits; thyself harmonised by the yoga of renunciation, thou shalt come unto Me when set free.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","28 of 34"]]},"g2-9-28":{"route":"#/gitav/9.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:28:en2","title":"Gita 9.28, in another translation","body":"Thus shalt thou be freed from the bondages of actions, bearing good and evil results: with the heart steadfast in the Yoga of renunciation, and liberated, thou shalt come unto Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","28 of 34"]]},"gv-9-29":{"route":"#/gitav/9.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:29:en","title":"Bhagavad Gita 9.29","text":"समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः ।\nये भजन्ति तु मां भक्त्या मयि ते तेषु चाप्यहम् ॥","lang":"sa","roman":"samo’haṃ sarvabhūteṣu na me dveṣyo’sti na priyaḥ |\nye bhajanti tu māṃ bhaktyā mayi te teṣu cāpyaham ||","body":"The same am I to all beings; there is none hateful to Me nor dear. They verily who worship Me with devotion, they are in Me, and I also in them.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","29 of 34"]]},"g2-9-29":{"route":"#/gitav/9.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:29:en2","title":"Gita 9.29, in another translation","body":"I am the same to all beings: to Me there is none hateful or dear. But those who worship Me with devotion, are in Me, and I too am in them.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","29 of 34"]]},"gv-9-30":{"route":"#/gitav/9.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:30:en","title":"Bhagavad Gita 9.30","text":"अपि चेत्सुदुराचारो भजते मामनन्यभाक् ।\nसाधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः ॥","lang":"sa","roman":"api cetsudurācāro bhajate māmananyabhāk |\nsādhureva sa mantavyaḥ samyagvyavasito hi saḥ ||","body":"Even if the most sinful worship Me, with un divided heart, he too must be accounted righteous, for he hath rightly resolved;","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","30 of 34"]]},"g2-9-30":{"route":"#/gitav/9.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:30:en2","title":"Gita 9.30, in another translation","body":"If even a very wicked person worships Me, with devotion to none else, he should be regarded as good, for he has rightly resolved.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","30 of 34"]]},"gv-9-31":{"route":"#/gitav/9.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:31:en","title":"Bhagavad Gita 9.31","text":"क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति ।\nकौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति ॥","lang":"sa","roman":"kṣipraṃ bhavati dharmātmā śaśvacchāntiṃ nigacchati |\nkaunteya pratijānīhi na me bhaktaḥ praṇaśyati ||","body":"Speedily he becometh dutiful and goeth to eternal peace; O Kaunteya, know thou for certain that My devotee perisheth never.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","31 of 34"]]},"g2-9-31":{"route":"#/gitav/9.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:31:en2","title":"Gita 9.31, in another translation","body":"Soon does he become righteous, and attain eternal Peace, O son of Kunti boldly canst thou proclaim, that My devotee is never destroyed.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","31 of 34"]]},"gv-9-32":{"route":"#/gitav/9.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:32:en","title":"Bhagavad Gita 9.32","text":"मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः ।\nस्त्रियो वैश्यास्तथा शूद्रास्तेऽपि यान्ति परां गतिम् ॥","lang":"sa","roman":"māṃ hi pārtha vyapāśritya ye’pi syuḥ pāpayonayaḥ |\nstriyo vaiśyāstathā śūdrāste’pi yānti parāṃ gatim ||","body":"They who take refuge with Me, O Partha, though of the womb of sin, women, Vaishyas, even Shûdras, they also tread the highest path.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","32 of 34"]]},"g2-9-32":{"route":"#/gitav/9.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:32:en2","title":"Gita 9.32, in another translation","body":"For, taking refuge in Me, they also, O son of Prithâ, who might be of inferior birth,—women, Vaishyas, as well as Sudras,—even they attain to the Supreme Goal.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","32 of 34"]]},"gv-9-33":{"route":"#/gitav/9.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:33:en","title":"Bhagavad Gita 9.33","text":"किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा ।\nअनित्यमसुखं लोकमिमं प्राप्य भजस्व माम् ॥","lang":"sa","roman":"kiṃ punarbrāhmaṇāḥ puṇyā bhaktā rājarṣayastathā |\nanityamasukhaṃ lokamimaṃ prāpya bhajasva mām ||","body":"How much rather then holy Brâhmanas and devoted royal saints; having obtained this transient joyless world, worship thou Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","33 of 34"]]},"g2-9-33":{"route":"#/gitav/9.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:33:en2","title":"Gita 9.33, in another translation","body":"What need to mention holy Brâhmanas, and devoted Râjarshis! Having obtained this transient, joyless world, worship thou Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","33 of 34"]]},"gv-9-34":{"route":"#/gitav/9.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:34:en","title":"Bhagavad Gita 9.34","text":"मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु ।\nमामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः ॥","lang":"sa","roman":"manmanā bhava madbhakto madyājī māṃ namaskuru |\nmāmevaiṣyasi yuktvaivamātmānaṃ matparāyaṇaḥ ||","body":"On Me fix thy mind, be devoted to Me; sacrifice to Me; prostrate thyself before Me; harmonised thus in the Self, thou shalt come unto Me, having Me as thy supreme goal.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","34 of 34"]]},"g2-9-34":{"route":"#/gitav/9.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 9 — The Way of the Kingly Knowledge and the Kingly Secret","src":"gita:9:34:en2","title":"Gita 9.34, in another translation","body":"Fill thy mind with Me, be My devotee, sacrifice unto Me, bow down to Me; thus having made thy heart steadfast in Me, taking Me as the Supreme Goal, thou shalt come to Me.","facts":[["Chapter","The Way of the Kingly Knowledge and the Kingly Secret"],["Verse","34 of 34"]]},"gv-10-1":{"route":"#/gitav/10.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:1:en","title":"Bhagavad Gita 10.1","text":"भूय एव महाबाहो शृणु मे परमं वचः ।\nयत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया ॥","lang":"sa","roman":"bhūya eva mahābāho śṛṇu me paramaṃ vacaḥ |\nyatte’haṃ prīyamāṇāya vakṣyāmi hitakāmyayā ||","body":"The Blessed Lord said: Again, O mighty-armed, hear thou My supreme word, that, desiring thy welfare, I will declare to thee who art beloved.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","1 of 42"]]},"g2-10-1":{"route":"#/gitav/10.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:1:en2","title":"Gita 10.1, in another translation","body":"Again, O mighty-armed, do thou listen to My supreme word, which I, wishing thy welfare, will tell thee who art delighted (to hear Me).","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","1 of 42"]]},"gv-10-2":{"route":"#/gitav/10.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:2:en","title":"Bhagavad Gita 10.2","text":"न मे विदुः सुरगणाः प्रभवं न महर्षयः ।\nअहमादिर्हि देवानां महर्षीणां च सर्वशः ॥","lang":"sa","roman":"na me viduḥ suragaṇāḥ prabhavaṃ na maharṣayaḥ |\nahamādirhi devānāṃ maharṣīṇāṃ ca sarvaśaḥ ||","body":"The multitude of the Shining Ones, or the great Rishis, know not my forthcoming, for I am the beginning of all the Shining Ones and the great Rishis.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","2 of 42"]]},"g2-10-2":{"route":"#/gitav/10.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:2:en2","title":"Gita 10.2, in another translation","body":"Neither the hosts of Devas, nor the great Rishis, know My origin, for in every way I am the source of all the Devas and the great Rishis.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","2 of 42"]]},"gv-10-3":{"route":"#/gitav/10.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:3:en","title":"Bhagavad Gita 10.3","text":"यो मामजमनादिं च वेत्ति लोकमहेश्वरम् ।\nअसम्मूढः स मर्त्येषु सर्वपापैः प्रमुच्यते ॥","lang":"sa","roman":"yo māmajamanādiṃ ca vetti lokamaheśvaram |\nasammūḍhaḥ sa martyeṣu sarvapāpaiḥ pramucyate ||","body":"He who knoweth Me, unborn, beginningless, the great Lord of the world, he among mortals without delusion, is liberated from all sin.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","3 of 42"]]},"g2-10-3":{"route":"#/gitav/10.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:3:en2","title":"Gita 10.3, in another translation","body":"He who knows Me, birthless and beginningless, the great Lord of worlds—he, among mortals, is undeluded, he is freed from all sins.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","3 of 42"]]},"gv-10-4":{"route":"#/gitav/10.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:4:en","title":"Bhagavad Gita 10.4","text":"बुद्धिर्ज्ञानमसंमोहः क्षमा सत्यं दमः शमः ।\nसुखं दुःखं भवोऽभावो भयं चाभयमेव च ॥","lang":"sa","roman":"buddhirjñānamasaṃmohaḥ kṣamā satyaṃ damaḥ śamaḥ |\nsukhaṃ duḥkhaṃ bhavo’bhāvo bhayaṃ cābhayameva ca ||","body":"Reason, wisdom, non-illusion, forgiveness, truth, self-restraint, calmness, pleasure, pain, existence, non-existence, fear, and also courage","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","4 of 42"]]},"g2-10-4":{"route":"#/gitav/10.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:4:en2","title":"Gita 10.4, in another translation","body":"Intellect, knowledge, non-delusion, forbearance, truth, restraint of the external senses, calmness of heart, happiness, misery, birth, death, fear, as well as fearlessness, non-injury, evenness, contentment, austerity, benevolence, good name, (as well as) ill-fame;—(these) different kinds of qualities of beings arise from Me alone.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","4 of 42"]]},"gv-10-5":{"route":"#/gitav/10.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:5:en","title":"Bhagavad Gita 10.5","text":"अहिंसा समता तुष्टिस्तपो दानं यशोऽयशः ।\nभवन्ति भावा भूतानां मत्त एव पृथग्विधाः ॥","lang":"sa","roman":"ahiṃsā samatā tuṣṭistapo dānaṃ yaśo’yaśaḥ |\nbhavanti bhāvā bhūtānāṃ matta eva pṛthagvidhāḥ ||","body":"Harmlessness, equanimity, content, austerity, almsgiving, fame and obloquy are the various characteristics of beings issuing from Me.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","5 of 42"]]},"gv-10-6":{"route":"#/gitav/10.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:6:en","title":"Bhagavad Gita 10.6","text":"महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा ।\nमद्भावा मानसा जाता येषां लोक इमाः प्रजाः ॥","lang":"sa","roman":"maharṣayaḥ sapta pūrve catvāro manavastathā |\nmadbhāvā mānasā jātā yeṣāṃ loka imāḥ prajāḥ ||","body":"The seven great Rishis, the ancient Four, and also the Manus, were born of My nature, and mind; of them this race was generated.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","6 of 42"]]},"g2-10-6":{"route":"#/gitav/10.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:6:en2","title":"Gita 10.6, in another translation","body":"The seven great Rishis as well as the four ancient Manus, possessed of powers like Me (due to their thoughts being fixed on Me), were born of (My) mind; from them are these creatures in the world.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","6 of 42"]]},"gv-10-7":{"route":"#/gitav/10.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:7:en","title":"Bhagavad Gita 10.7","text":"एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः ।\nसोऽविकम्पेन योगेन युज्यते नात्र संशयः ॥","lang":"sa","roman":"etāṃ vibhūtiṃ yogaṃ ca mama yo vetti tattvataḥ |\nso’vikampena yogena yujyate nātra saṃśayaḥ ||","body":"He who knows in essence that sovereignty and yoga of Mine, he is harmonised by unfaltering yoga; there is no doubt thereof.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","7 of 42"]]},"g2-10-7":{"route":"#/gitav/10.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:7:en2","title":"Gita 10.7, in another translation","body":"He who in reality knows these manifold manifestations of My being and (this) Yoga power of Mine, becomes established in the unshakable Yoga; there is no doubt about it.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","7 of 42"]]},"gv-10-8":{"route":"#/gitav/10.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:8:en","title":"Bhagavad Gita 10.8","text":"अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते ।\nइति मत्वा भजन्ते मां बुधा भावसमन्विताः ॥","lang":"sa","roman":"ahaṃ sarvasya prabhavo mattaḥ sarvaṃ pravartate |\niti matvā bhajante māṃ budhā bhāvasamanvitāḥ ||","body":"I am the Generator of all; all evolves from Me; understanding thus, the wise adore Me in rapt emotion.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","8 of 42"]]},"g2-10-8":{"route":"#/gitav/10.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:8:en2","title":"Gita 10.8, in another translation","body":"l am the origin of all, from Me everything evolves;—thus thinking the wise worship Me with loving consciousness.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","8 of 42"]]},"gv-10-9":{"route":"#/gitav/10.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:9:en","title":"Bhagavad Gita 10.9","text":"मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम् ।\nकथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च ॥","lang":"sa","roman":"maccittā madgataprāṇā bodhayantaḥ parasparam |\nkathayantaśca māṃ nityaṃ tuṣyanti ca ramanti ca ||","body":"Mindful of Me, their life hidden in Me, illumining each other, ever conversing about Me, they are content and joyful.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","9 of 42"]]},"g2-10-9":{"route":"#/gitav/10.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:9:en2","title":"Gita 10.9, in another translation","body":"With their minds wholly in Me, with their senses absorbed in Me, enlightening one another, and always speaking of Me, they are satisfied and delighted.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","9 of 42"]]},"gv-10-10":{"route":"#/gitav/10.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:10:en","title":"Bhagavad Gita 10.10","text":"तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम् ।\nददामि बुद्धियोगं तं येन मामुपयान्ति ते ॥","lang":"sa","roman":"teṣāṃ satatayuktānāṃ bhajatāṃ prītipūrvakam |\ndadāmi buddhiyogaṃ taṃ yena māmupayānti te ||","body":"To these, ever harmonious, worshipping in love, I give the yoga of discrimination by which they come unto Me.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","10 of 42"]]},"g2-10-10":{"route":"#/gitav/10.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:10:en2","title":"Gita 10.10, in another translation","body":"To them, ever steadfast and serving Me with affection, I give that Buddhi Yoga by which they come unto Me.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","10 of 42"]]},"gv-10-11":{"route":"#/gitav/10.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:11:en","title":"Bhagavad Gita 10.11","text":"तेषामेवानुकम्पार्थमहमज्ञानजं तमः ।\nनाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता ॥","lang":"sa","roman":"teṣāmevānukampārthamahamajñānajaṃ tamaḥ |\nnāśayāmyātmabhāvastho jñānadīpena bhāsvatā ||","body":"Out of pure compassion for them, dwelling within their Self, I destroy the ignorance-born darkness by the shining lamp of wisdom.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","11 of 42"]]},"g2-10-11":{"route":"#/gitav/10.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:11:en2","title":"Gita 10.11, in another translation","body":"Out of mere compassion for them, [paragraph continues] I, abiding in their hearts, destroy the darkness (in them) born of ignorance, by the luminous lamp of knowledge.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","11 of 42"]]},"gv-10-12":{"route":"#/gitav/10.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:12:en","title":"Bhagavad Gita 10.12","text":"परं ब्रह्म परं धाम पवित्रं परमं भवान् ।\nपुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम् ॥","lang":"sa","roman":"paraṃ brahma paraṃ dhāma pavitraṃ paramaṃ bhavān |\npuruṣaṃ śāśvataṃ divyamādidevamajaṃ vibhum ||","body":"Arjuna said: Thou art the supreme Eternal, the supreme Abode, the supreme Purity, eternal divine man, primeval Deity, unborn, the Lord!","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","12 of 42"]]},"g2-10-12":{"route":"#/gitav/10.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:12:en2","title":"Gita 10.12, in another translation","body":"The Supreme Brahman, the Supreme Abode, the Supreme Purifier, art Thou. All the Rishis, the Deva-Rishi Nârada as well as Asita, Devala and Vyâsa have declared Thee as the Eternal, the Self-luminous Purusha, the first Deva, Birth-less and All-pervading. So also Thou Thyself sayest to me.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","12 of 42"]]},"gv-10-13":{"route":"#/gitav/10.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:13:en","title":"Bhagavad Gita 10.13","text":"आहुस्त्वामृषयः सर्वे देवर्षिर्नारदस्तथा ।\nअसितो देवलो व्यासः स्वयं चैव ब्रवीषि मे ॥","lang":"sa","roman":"āhustvāmṛṣayaḥ sarve devarṣirnāradastathā |\nasito devalo vyāsaḥ svayaṃ caiva bravīṣi me ||","body":"All the Rishis have thus acclaimed Thee, as also the divine Rishi, Nârada; so Asita, Devala, and Vyâsa; and now Thou Thyself tellest it me.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","13 of 42"]]},"gv-10-14":{"route":"#/gitav/10.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:14:en","title":"Bhagavad Gita 10.14","text":"सर्वमेतदृतं मन्ये यन्मां वदसि केशव ।\nन हि ते भगवन् व्यक्तिं विदुर्देवा न दानवाः ॥","lang":"sa","roman":"sarvametadṛtaṃ manye yanmāṃ vadasi keśava |\nna hi te bhagavan vyaktiṃ vidurdevā na dānavāḥ ||","body":"All this I believe true that Thou sayest to me, O Keshava. Thy manifestation, O Blessed Lord, neither Shining Ones nor Dânavas comprehend.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","14 of 42"]]},"g2-10-14":{"route":"#/gitav/10.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:14:en2","title":"Gita 10.14, in another translation","body":"I regard all this that Thou sayest to me as true, O Keshava. Verily, O Bhagavân, neither the Devas nor the Dânavas know Thy manifestation.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","14 of 42"]]},"gv-10-15":{"route":"#/gitav/10.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:15:en","title":"Bhagavad Gita 10.15","text":"स्वयमेवात्मनाऽत्मानं वेत्थ त्वं पुरुषोत्तम ।\nभूतभावन भूतेश देवदेव जगत्पते ॥","lang":"sa","roman":"svayamevātmanā’tmānaṃ vettha tvaṃ puruṣottama |\nbhūtabhāvana bhūteśa devadeva jagatpate ||","body":"Thyself indeed knowest Thyself by Thyself, O Purushottama; Source of beings, Lord of beings, Shining One of Shining Ones, Ruler of the world!","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","15 of 42"]]},"g2-10-15":{"route":"#/gitav/10.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:15:en2","title":"Gita 10.15, in another translation","body":"Verily, Thou Thyself knowest Thyself by Thyself, O Purusha Supreme, O Source of beings, O Lord of beings, O Deva of Devas, O Ruler of the world.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","15 of 42"]]},"gv-10-16":{"route":"#/gitav/10.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:16:en","title":"Bhagavad Gita 10.16","text":"वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः ।\nयाभिर्विभूतिभिर्लोकानिमांस्त्वं व्याप्य तिष्ठसि ॥","lang":"sa","roman":"vaktumarhasyaśeṣeṇa divyā hyātmavibhūtayaḥ |\nyābhirvibhūtibhirlokānimāṃstvaṃ vyāpya tiṣṭhasi ||","body":"Deign to tell without reserve of Thine own divine glories, by which glories Thou remainest, pervading these worlds.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","16 of 42"]]},"g2-10-16":{"route":"#/gitav/10.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:16:en2","title":"Gita 10.16, in another translation","body":"Thou shouldst indeed speak, without reserve, of Thy divine attributes by which, filling all these worlds, Thou existest.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","16 of 42"]]},"gv-10-17":{"route":"#/gitav/10.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:17:en","title":"Bhagavad Gita 10.17","text":"कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन् ।\nकेषु केषु च भावेषु चिन्त्योऽसि भगवन्मया ॥","lang":"sa","roman":"kathaṃ vidyāmahaṃ yogiṃstvāṃ sadā paricintayan |\nkeṣu keṣu ca bhāveṣu cintyo’si bhagavanmayā ||","body":"How may I know thee, O Yogi, by constant meditation? In what, in what aspects art Thou to be thought of by me, O blessed Lord?","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","17 of 42"]]},"g2-10-17":{"route":"#/gitav/10.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:17:en2","title":"Gita 10.17, in another translation","body":"How shall I, O Yogin, meditate ever to know Thee? In what things, Bhagavân, art Thou to be thought of by me?","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","17 of 42"]]},"gv-10-18":{"route":"#/gitav/10.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:18:en","title":"Bhagavad Gita 10.18","text":"विस्तरेणात्मनो योगं विभूतिं च जनार्दन ।\nभूयः कथय तृप्तिर्हि शृण्वतो नास्ति मेऽमृतम् ॥","lang":"sa","roman":"vistareṇātmano yogaṃ vibhūtiṃ ca janārdana |\nbhūyaḥ kathaya tṛptirhi śṛṇvato nāsti me’mṛtam ||","body":"In detail tell me again of Thy yoga and glory, O Janardana; for me there is never satiety in hearing thy life-giving words.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","18 of 42"]]},"g2-10-18":{"route":"#/gitav/10.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:18:en2","title":"Gita 10.18, in another translation","body":"Speak to me again in detail, Jnanârdana, of Thy Yoga-powers and attributes; for I am never satiated in hearing the ambrosia (of Thy speech).","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","18 of 42"]]},"gv-10-19":{"route":"#/gitav/10.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:19:en","title":"Bhagavad Gita 10.19","text":"हन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतयः ।\nप्राधान्यतः कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे ॥","lang":"sa","roman":"hanta te kathayiṣyāmi divyā hyātmavibhūtayaḥ |\nprādhānyataḥ kuruśreṣṭha nāstyanto vistarasya me ||","body":"The Blessed Lord said: Blessed be thou! I will declare to thee My divine glory by its chief characteristics, O best of the Kurus; there is no end to details of Me.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","19 of 42"]]},"g2-10-19":{"route":"#/gitav/10.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:19:en2","title":"Gita 10.19, in another translation","body":"I shall speak to thee now, O best of the Kurus, of My divine attributes, according to their prominence; there is no end to the particulars of My manifestation.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","19 of 42"]]},"gv-10-20":{"route":"#/gitav/10.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:20:en","title":"Bhagavad Gita 10.20","text":"अहमात्मा गुडाकेश सर्वभूताशयस्थितः ।\nअहमादिश्च मध्यं च भूतानामन्त एव च ॥","lang":"sa","roman":"ahamātmā guḍākeśa sarvabhūtāśayasthitaḥ |\nahamādiśca madhyaṃ ca bhūtānāmanta eva ca ||","body":"I, O Gudakesha, am the Self, seated in the heart of all beings; I am the beginning, the middle, and also the end of all beings.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","20 of 42"]]},"g2-10-20":{"route":"#/gitav/10.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:20:en2","title":"Gita 10.20, in another translation","body":"I am the Self, O Gudâkesha, existent in the heart of all beings; I am the beginning, the middle, and also the end of all beings.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","20 of 42"]]},"gv-10-21":{"route":"#/gitav/10.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:21:en","title":"Bhagavad Gita 10.21","text":"आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान् ।\nमरीचिर्मरुतामस्मि नक्षत्राणामहं शशी ॥","lang":"sa","roman":"ādityānāmahaṃ viṣṇurjyotiṣāṃ raviraṃśumān |\nmarīcirmarutāmasmi nakṣatrāṇāmahaṃ śaśī ||","body":"Of the Adityas I am Vishnu; of radiances the glorious sun; I am Marîchi of the Maruts; of the asterisms the Moon am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","21 of 42"]]},"g2-10-21":{"route":"#/gitav/10.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:21:en2","title":"Gita 10.21, in another translation","body":"Of the Adityas, I am Vishnu; of luminaries, the radiant Sun; of the winds, I am Marichi; of the asterisms, the Moon.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","21 of 42"]]},"gv-10-22":{"route":"#/gitav/10.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:22:en","title":"Bhagavad Gita 10.22","text":"वेदानां सामवेदोऽस्मि देवानामस्मि वासवः ।\nइन्द्रियाणां मनश्चास्मि भूतानामस्मि चेतना ॥","lang":"sa","roman":"vedānāṃ sāmavedo’smi devānāmasmi vāsavaḥ |\nindriyāṇāṃ manaścāsmi bhūtānāmasmi cetanā ||","body":"Of the Vedas I am the Sâma-Veda; I am Vâsava of the Shining Ones; and of the senses I am the mind; I am of living beings the intelligence.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","22 of 42"]]},"g2-10-22":{"route":"#/gitav/10.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:22:en2","title":"Gita 10.22, in another translation","body":"I am the Sâma-Veda of the Vedas, and Vâsava (Indra) of the gods; of the senses I am Manas, and intelligence in living beings am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","22 of 42"]]},"gv-10-23":{"route":"#/gitav/10.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:23:en","title":"Bhagavad Gita 10.23","text":"रुद्राणां शङ्करश्चास्मि वित्तेशो यक्षरक्षसाम् ।\nवसूनां पावकश्चास्मि मेरुः शिखरिणामहम् ॥","lang":"sa","roman":"rudrāṇāṃ śaṅkaraścāsmi vitteśo yakṣarakṣasām |\nvasūnāṃ pāvakaścāsmi meruḥ śikhariṇāmaham ||","body":"And of the Rudras Shañkara am I; Vittesha of the Yakshas and Râkshasas; and of the Vasus I am Pâvaka; Meru of high mountains am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","23 of 42"]]}});
